s":["w","kinds","ids","versions","kind","id","version"],"proargtypes":["2950","1009","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":["2950","1009","2951","1009","25","2950","25"],"pronargdefaults":0},"defaultExpression":null,"app":false,"public":false,"lineageRoster":["application_scope_source_edges(uuid,text,uuid,text)","application_scope_source_edges_before_knowledge_versions(uuid,text,uuid,text)","knowledge_version_source_edges(uuid,text,uuid,text)","scope_source_ancestors(uuid,text,uuid)","scope_source_ancestors_before_workflow_run(uuid,text,uuid)","scope_source_ancestors_before_browser_session(uuid,text,uuid)","scope_source_ancestors_before_browser_profile(uuid,text,uuid)","scope_source_table(text)","scope_source_table_before_knowledge_versions(text)","scope_source_table_before_persistent_context(text)","scope_source_table_before_media(text)","application_native_source_edges_dispatch(uuid,text,uuid,text)"],"template":"\nDECLARE nodes jsonb;\nBEGIN\n IF kinds IS NULL OR ids IS NULL OR versions IS NULL\n  OR cardinality(kinds) IS DISTINCT FROM cardinality(ids) OR cardinality(ids) IS DISTINCT FROM cardinality(versions)\n  OR cardinality(ids) NOT BETWEEN 1 AND 100 OR array_position(kinds,NULL) IS NOT NULL\n  OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023''; END IF;\n -- R2 canonical entity leaf transport, after the original complete input validation.\n IF w IS NOT NULL AND cardinality(ids)=1\n  AND array_ndims(kinds)=1 AND array_lower(kinds,1)=1\n  AND array_ndims(ids)=1 AND array_lower(ids,1)=1\n  AND array_ndims(versions)=1 AND array_lower(versions,1)=1\n  AND kinds[1] IN(''entity'',''memory'')\n  AND NOT EXISTS(SELECT 1 FROM public.scope_derivations d\n   WHERE d.workspace_id=w AND d.resource_kind=kinds[1] AND d.resource_id=ids[1])\n  AND (kinds[1]=''entity'' AND NOT EXISTS(SELECT 1 FROM public.entities e\n    WHERE e.workspace_id=w AND e.superseded_by=ids[1])\n   OR kinds[1]=''memory'' AND NOT EXISTS(SELECT 1 FROM public.memories m\n    WHERE m.workspace_id=w AND m.superseded_by=ids[1]))\n  AND (SELECT count(*)=12 AND coalesce(bool_and(public.application_field_digest(jsonb_build_object(''name'',r.proname,''namespace'',r.pronamespace,''body'',r.prosrc,''config'',r.proconfig,''language'',r.prolang,''securityDefiner'',r.prosecdef,''volatility'',r.provolatile,''strict'',r.proisstrict,''parallel'',r.proparallel))=pin.fingerprint),false)\n   FROM (VALUES __PINS__) pin(function_oid,fingerprint)\n   JOIN pg_catalog.pg_proc r ON r.oid=pin.function_oid) THEN\n  RETURN QUERY SELECT kinds[1],ids[1],versions[1];\n  RETURN;\n END IF;\n WITH RECURSIVE lineage(kind,id,version) AS (\n  SELECT * FROM unnest(kinds,ids,versions)\n  UNION\n  SELECT next.kind,next.id,next.version FROM lineage l\n   CROSS JOIN LATERAL application_scope_source_edges(w,l.kind,l.id,l.version) next\n ), bounded AS MATERIALIZED(SELECT * FROM lineage LIMIT 4097)\n SELECT coalesce(jsonb_agg(to_jsonb(b)),''[]'') INTO nodes FROM bounded b;\n -- UNION terminates native high-water back-edges (including a row edited from\n -- its earlier version). New field-child graphs are separately depth bounded\n -- by capture and the admitted reader; no app role may author metadata edges.\n IF jsonb_array_length(nodes)>4096 OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n\n  WHERE n->>''version'' IS NULL OR n->>''kind'' IS NULL OR n->>''id'' IS NULL\n   OR n->>''kind''=''application_field'' AND NOT EXISTS(SELECT 1 FROM application_field_observations o\n    WHERE o.workspace_id=w AND o.resource_id=(n->>''id'')::uuid AND o.version=n->>''version'')) THEN\n  RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023''; END IF;\n RETURN QUERY SELECT DISTINCT n->>''kind'',(n->>''id'')::uuid,n->>''version'' FROM jsonb_array_elements(nodes) n;\nEND "},{"signature":"application_scope_source_edges(uuid,text,uuid,text)","language":"plpgsql","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"application_scope_source_edges","prorows":1000,"pronargs":4,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","i","t","t","t"],"proargnames":["w","k","i","v","kind","id","version"],"proargtypes":["2950","25","2950","25"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":["2950","25","2950","25","25","2950","25"],"pronargdefaults":0},"defaultExpression":null,"app":false,"public":false,"dependencies":[],"body":"eb8966087803239c93bcdac1736ba917251adaed34c244feb3f80bc80d2c9077"},{"signature":"application_scope_source_edges_before_knowledge_versions(uuid,text,uuid,text)","language":"sql","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"application_scope_source_edges_before_knowledge_versions","prorows":1000,"pronargs":4,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","i","t","t","t"],"proargnames":["w","k","i","v","kind","id","version"],"proargtypes":["2950","25","2950","25"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":["2950","25","2950","25","25","2950","25"],"pronargdefaults":0},"defaultExpression":null,"app":false,"public":false,"dependencies":[],"body":"23d72c938e15ccb1877e6deabc9b75cd44c92f2539b0afd1c0456517086d6a03"},{"signature":"application_session_eval_domain(uuid,text,uuid,text[],jsonb)","language":"plpgsql","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"application_session_eval_domain","prorows":0,"pronargs":5,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prose