defaultExpression":null,"app":false,"public":false,"dependencies":[],"body":"da5916c9103078288651ffd20c529938e97281dccf610a1fccee4d78e1a29f68"}]'::jsonb) LOOP
 IF expected->>'signature' IN ('session_personal_audience(sessions)','session_workspace_audience(sessions)','session_project_audience(sessions,boolean)') THEN expected:=jsonb_set(expected,'{metadata,proargtypes,0}',to_jsonb(('public.sessions'::regtype::oid)::text),false);END IF;
 SELECT * INTO actual FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('public.'||(expected->>'signature'));
 IF actual.oid IS NULL OR actual.proowner IS DISTINCT FROM (SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass)
 OR actual.pronamespace<>'public'::regnamespace OR actual.prolang IS DISTINCT FROM (SELECT oid FROM pg_language WHERE lanname=expected->>'language')
 OR (to_jsonb(actual)-ARRAY['oid','prosrc','proowner','proacl','prolang','pronamespace','proargdefaults']) IS DISTINCT FROM expected->'metadata'
 OR pg_get_expr(actual.proargdefaults,0) IS DISTINCT FROM expected->>'defaultExpression'
 OR NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=actual.proowner AND a.grantor=actual.proowner AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
 OR EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantor<>actual.proowner OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR a.grantee<>actual.proowner
  AND NOT(a.grantee=0 AND (expected->>'public')::boolean)
  AND NOT(a.grantee<>0 AND ((expected->>'app')::boolean OR expected->>'signature'='project_labels_allowed(jsonb,uuid,text[],boolean)') AND EXISTS(SELECT 1 FROM pg_roles WHERE oid=a.grantee AND rolname='app_user')))
 OR (expected->>'app')::boolean AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname='app_user') AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a JOIN pg_roles r ON r.oid=a.grantee WHERE r.rolname='app_user' AND a.privilege_type='EXECUTE')
 OR (expected->>'public')::boolean AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE')
 THEN RAISE EXCEPTION 'Flat covered manifest prerequisite metadata changed: %',expected->>'signature';END IF;
 IF expected ? 'roster' THEN
  SELECT string_agg(format('(%s::oid,%L::text)',p.oid,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')),',' ORDER BY p.oid),count(*) INTO pins,pin_count
  FROM jsonb_array_elements_text(expected->'roster') r(signature) JOIN pg_proc p ON p.oid=to_regprocedure('public.'||r.signature);
  IF pin_count<>jsonb_array_length(expected->'roster') OR actual.prosrc IS DISTINCT FROM replace(expected->>'template','__PINS__',pins) THEN
   RAISE EXCEPTION 'Flat covered manifest prerequisite guard changed: %',expected->>'signature';END IF;
 ELSIF expected ? 'lineageRoster' THEN
  lineage_values:='';
  FOR dependency IN SELECT value FROM jsonb_array_elements(expected->'lineageRoster') LOOP
   SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.'||(dependency#>>'{}'));
   IF actual.oid IS NULL THEN RAISE EXCEPTION 'Flat covered manifest lineage dependency missing';END IF;
   semantic_hash:=encode(sha256(convert_to(jsonb_build_object('name',actual.proname,'namespace',actual.pronamespace,'body',actual.prosrc,'config',actual.proconfig,'language',actual.prolang,'securityDefiner',actual.prosecdef,'volatility',actual.provolatile,'strict',actual.proisstrict,'parallel',actual.proparallel)::text,'UTF8')),'hex');
   lineage_values:=lineage_values||CASE WHEN lineage_values='' THEN '' ELSE ',' END||format('(%s::oid,%L::text)',actual.oid,semantic_hash);
  END LOOP;
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.'||(expected->>'signature'));
  IF actual.prosrc IS DISTINCT FROM replace(expected->>'template','__PINS__',lineage_values) THEN RAISE EXCEPTION 'Flat covered manifest lineage executable changed';END IF;
 ELSIF NOT expected ? 'special' THEN
  body:=actual.prosrc;
  FOR dependency IN SELECT value FROM jsonb_array_elements(expected->'dependencies') LOOP
   SELECT CASE WHEN dependency->>'kind'='fingerprint' THEN encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') ELSE encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') END INTO old_pin
   FROM pg_proc p WHERE p.oid=to_regprocedure('public.'||(dependency->>'signature'));
   IF old_pin IS NULL OR (length(body)-length(replace(body,old_pin,'')))/64<>(dependency->>'count')::integer THEN RAISE EXCEPTION 'Flat covered manifest prerequisite dependency changed: %',expected->>'signature';END IF;
   body:=replace(body,old_pin,dependency->>'marker');
  END LOOP;
  IF encode(sha256(convert_to(body,'UTF8')),'hex') IS DISTINCT FROM expected->>'body' THEN RAISE EXCEPTION 'Flat covered manifest prerequisite body changed: %',expected->>'signature';END IF;
 END IF;
 END LOOP;
END $flat_covered_manifest$;

DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('native_detached_eval_point_state(uuid,text,uuid,text[],jsonb,jsonb)')) IS DISTINCT FROM '346493e5b86ec237753610de954d6e875418ff84b0f988ea50a410e2d7bf7d22' THEN RAISE EXCEPTION 'Native turn prerequisite changed: native_detached_eval_point_state';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('native_detached_eval_scan(uuid,uuid,text,integer,text[],jsonb,jsonb,jsonb,jsonb)')) IS DISTINCT FROM '849e820422d65f342424f2ab5738ec9dacc561a575c34fb9fcbdd8d685f76b3a' THEN RAISE EXCEPTION 'Native turn prerequisite changed: native_detached_eval_scan';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('native_detached_eval_domain(uuid,text,uuid,text[],jsonb,jsonb)')) IS DISTINCT FROM 'e077bdad49c376215152d21d1b6789ee1e01ea2a26107a979842067028692407' THEN RAISE EXCEPTION 'Native turn prerequisite changed: native_detached_eval_domain';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('native_detached_eval_envelope(uuid,text,uuid,text,text[],jsonb,jsonb)')) IS DISTINCT FROM '1abd5a1618bdeae7307910af675c46787c3b46160da15f1973745a2a2db73898' THEN RAISE EXCEPTION 'Native turn prerequisite changed: native_detached_eval_envelope';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('native_detached_eval_field(uuid,uuid,text,jsonb,jsonb)')) IS DISTINCT FROM '2ba026df8048ab182f4943bfc74251ac3dd94588ce9b29102b4859855c492d79' THEN RAISE EXCEPTION 'Native turn prerequisite changed: native_detached_eval_field';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('native_detached_eval_scope(uuid,text,uuid,text,jsonb,jsonb)')) IS DISTINCT FROM 'f134892ba519a79e50038014a7dd9c1ba08917edc5adf5c93870774d06a96281' THEN RAISE EXCEPTION 'Native turn prerequisite changed: native_detached_eval_scope';END IF;END $$;
CREATE OR REPLACE FUNCTION public.native_turn_key(n jsonb) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT CASE n->>'tag'
 WHEN 'source' THEN jsonb_build_array('source',n->>'kind',n->>'id',n->>'version')::text
 WHEN 'point' THEN jsonb_build_array('point',n->>'kind',n->>'id',n->'fields')::text
 ELSE NULL END
$$;
REVOKE ALL ON FUNCTION public.native_turn_key(jsonb) FROM PUBLIC;


CREATE OR REPLACE FUNCTION public.native_turn_topology(nodes jsonb, edges jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,pg_temp AS $$
DECLARE keys text[];index_map jsonb;reverse_edges jsonb;degree_map jsonb;degrees integer[];queue integer[]:='{}';
 cursor_index integer:=1;item integer;parent_index integer;n integer;result jsonb:='[]';
BEGIN
 SELECT array_agg(public.native_turn_key(value) ORDER BY public.native_turn_key(value)) INTO keys FROM jsonb_array_elements(nodes);
 n:=coalesce(cardinality(keys),0);IF n=0 THEN RETURN '[]';END IF;
 IF n>4096 OR jsonb_array_length(edges)>16384 OR cardinality(keys)<>(SELECT count(DISTINCT k) FROM unnest(keys) k) THEN RETURN NULL;END IF;
 SELECT jsonb_object_agg(k,ord) INTO index_map FROM unnest(keys) WITH ORDINALITY q(k,ord);
 WITH e AS MATERIALIZED(SELECT (index_map->>public.native_turn_key(value->'parent'))::integer p,
   (index_map->>public.native_turn_key(value->'child'))::integer c FROM jsonb_array_elements(edges)),
 r AS(SELECT c,jsonb_agg(p) parents FROM e GROUP BY c),d AS(SELECT p,count(*) degree FROM e GROUP BY p)
 SELECT (SELECT jsonb_object_agg(c,parents) FROM r),(SELECT jsonb_object_agg(p,degree) FROM d)
 INTO reverse_edges,degree_map;
 SELECT array_agg(coalesce((degree_map->>i::text)::integer,0) ORDER BY i) INTO degrees FROM generate_series(1,n) i;
 FOR item IN 1..n LOOP IF degrees[item]=0 THEN queue:=array_append(queue,item);END IF;END LOOP;
 WHILE cursor_index<=cardinality(queue) LOOP
  item:=queue[cursor_index];cursor_index:=cursor_index+1;result:=result||jsonb_build_array(keys[item]);
  FOR parent_index IN SELECT value::integer FROM jsonb_array_elements_text(coalesce(reverse_edges->item::text,'[]')) LOOP
   degrees[parent_index]:=degrees[parent_index]-1;
   IF degrees[parent_index]=0 THEN queue:=array_append(queue,parent_index);END IF;
  END LOOP;
 END LOOP;
 IF jsonb_array_length(result)<>n THEN RETURN NULL;END IF;RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.native_turn_topology(jsonb,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.native_turn_edges(w uuid,frontier jsonb)
RETURNS TABLE(parent jsonb,child jsonb,edge_kind text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 WITH RECURSIVE f AS MATERIALIZED(SELECT value n FROM jsonb_array_elements(frontier)),
 -- Canonical file ancestry emits ALL predecessors, with the root's requested
 -- version on each edge. Immediate-only edges would alter the edge witness.
 predecessors(root,id) AS (
  SELECT n,wf.id FROM f JOIN workspace_files wf ON n->>'tag'='source'
   AND n->>'kind'='workspace_file' AND wf.workspace_id=w AND wf.id=(n->>'id')::uuid
  UNION
  SELECT p.root,wf.id FROM predecessors p JOIN workspace_files wf
   ON wf.workspace_id=w AND wf.superseded_by=p.id
 ), e AS (
  SELECT n parent,jsonb_build_object('tag','source','kind',s.source_kind,'id',s.source_id,'version',s.source_version) child,'derivation'::text edge_kind
  FROM f JOIN scope_derivations d ON n->>'tag'='source' AND d.workspace_id=w
   AND d.resource_kind=n->>'kind' AND d.resource_id=(n->>'id')::uuid
  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id
  UNION ALL
  SELECT n,jsonb_build_object('tag','source','kind',o.source_kind,'id',o.source_id,'version',o.source_version),'observation'
  FROM f JOIN application_field_observations o ON n->>'tag'='source' AND n->>'kind'='application_field'
   AND o.workspace_id=w AND o.resource_id=(n->>'id')::uuid AND o.version=n->>'version'
  UNION ALL
  SELECT n,jsonb_build_object('tag','source','kind',s.source_kind,'id',s.source_id,'version',s.source_version),'observation_child'
  FROM f JOIN application_field_observation_sources s ON n->>'tag'='source' AND n->>'kind'='application_field'
   AND s.workspace_id=w AND s.resource_id=(n->>'id')::uuid AND s.version=n->>'version'
  UNION ALL
  SELECT root,jsonb_build_object('tag','source','kind','workspace_file','id',id,'version',root->>'version'),'predecessor'
  FROM predecessors WHERE id<>(root->>'id')::uuid
  UNION ALL
  -- A point dependency is added even when it was filtered from an older scan.
  SELECT n,jsonb_build_object('tag','point','kind',r.type_key,'id',r.resource_id,'fields',to_jsonb(r.fields)),'field_point'
  FROM f JOIN application_field_resources r ON n->>'tag'='source' AND n->>'kind'='application_field'
   AND r.workspace_id=w AND r.id=(n->>'id')::uuid
  WHERE r.origin='{"kind":"native","moduleKey":"native"}'::jsonb
   AND r.type_key IN('session_message','session_message_annotation') AND r.selected_version IS NULL
   AND r.selection IN('read','query','identity')
  UNION ALL
  -- Every physical row, not only admitted/recorded domain candidates.
  SELECT n,jsonb_build_object('tag','point','kind',q.type_key,'id',m.id,'fields',q.domain->'fields'),'domain_candidate'
  FROM f JOIN application_query_domains q ON n->>'tag'='source' AND n->>'kind'='application_query_domain'
   AND q.workspace_id=w AND q.id=(n->>'id')::uuid
  JOIN session_messages m ON m.workspace_id=w AND m.session_id=(q.domain->>'sessionId')::uuid
   AND m.sequence_num<=(q.domain->>'throughSequence')::integer
  WHERE q.origin='{"kind":"native","moduleKey":"native"}'::jsonb
   AND q.type_key IN('session_message','session_message_annotation')
   AND q.domain->>'kind'='session_query_domain_v1'
  UNION ALL
  SELECT n,jsonb_build_object('tag','source','kind','session_message','id',m.id,'version',m.scope_version::text),'point_body'
  FROM f JOIN session_messages m ON n->>'tag'='point' AND m.workspace_id=w AND m.id=(n->>'id')::uuid
  UNION ALL
  SELECT n,jsonb_build_object('tag','source','kind','session_context_revision','id',r.id,'version',r.scope_version::text),'point_head'
  FROM f JOIN session_messages m ON n->>'tag'='point' AND n->>'kind'='session_message_annotation' AND m.workspace_id=w AND m.id=(n->>'id')::uuid
  JOIN session_message_annotation_heads h ON h.workspace_id=w AND h.session_id=m.session_id AND h.message_id=m.id
  JOIN session_context_scope_revisions r ON r.workspace_id=w AND r.id=h.scope_revision_id
   AND r.session_id=m.session_id AND r.parent_kind='message_annotation' AND r.parent_id=m.id
  UNION ALL
  -- Conservative dependency: parent-message full closure, never parent ID alone.
  SELECT n,jsonb_build_object('tag','source','kind','session_message','id',m.id,'version',m.scope_version::text),'revision_parent'
  FROM f JOIN session_context_scope_revisions r ON n->>'tag'='source' AND n->>'kind'='session_context_revision'
   AND r.workspace_id=w AND r.id=(n->>'id')::uuid AND r.parent_kind='message_annotation'
  JOIN session_messages m ON m.workspace_id=w AND m.session_id=r.session_id AND m.id=r.parent_id
 ) SELECT DISTINCT parent,child,edge_kind FROM e
$$;
REVOKE ALL ON FUNCTION public.native_turn_edges(uuid,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.native_turn_privacy_edges(w uuid,frontier jsonb)
RETURNS TABLE(parent jsonb,child jsonb)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 WITH f AS MATERIALIZED(SELECT value n FROM jsonb_array_elements(frontier)), e AS (
 SELECT n parent,jsonb_build_object('kind',s.source_kind,'id',s.source_id) child
 FROM f JOIN scope_derivations d ON d.workspace_id=w AND d.resource_kind=n->>'kind' AND d.resource_id=(n->>'id')::uuid
 JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id
 UNION ALL
 SELECT n,jsonb_build_object('kind',o.source_kind,'id',o.source_id)
 FROM f JOIN application_field_observations o ON n->>'kind'='application_field' AND o.workspace_id=w AND o.resource_id=(n->>'id')::uuid
 UNION ALL
 SELECT n,jsonb_build_object('kind',s.source_kind,'id',s.source_id)
 FROM f JOIN application_field_observation_sources s ON n->>'kind'='application_field' AND s.workspace_id=w AND s.resource_id=(n->>'id')::uuid
 UNION ALL
 SELECT n,jsonb_build_object('kind','session_message','id',r.resource_id)
 FROM f JOIN application_field_resources r ON n->>'kind'='application_field' AND r.workspace_id=w AND r.id=(n->>'id')::uuid
 WHERE r.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND r.type_key IN('session_message','session_message_annotation')
 ) SELECT DISTINCT parent,child FROM e
$$;
REVOKE ALL ON FUNCTION public.native_turn_privacy_edges(uuid,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.native_turn_metadata_acquire(w uuid,roots jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $body$
DECLARE
 actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 acting uuid:=nullif(current_setting('app.v2_assistant_id',true),'')::uuid;
 nodes jsonb;frontier jsonb;next_nodes jsonb;edges jsonb:='[]';batch jsonb;
 privacy_nodes jsonb;privacy_frontier jsonb;privacy_edges jsonb:='[]';privacy_parents jsonb;
 native_metadata jsonb;field_metadata jsonb;domains jsonb;candidates jsonb;point_metadata jsonb;parents jsonb;
 derivations jsonb;context jsonb;locks jsonb;witness jsonb;remaining jsonb;ready jsonb;order_json jsonb:='[]';
 reasons text[]:='{}';step integer:=0;counts jsonb;
BEGIN
 -- These are eligibility/profile gates only, not all actor permissions.
 IF w IS NULL OR actor IS NULL OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.programmatic_candidate_source',true),'') IS NOT NULL
  OR nullif(current_setting('app.workflow_schedule_review',true),'') IS NOT NULL
  OR nullif(current_setting('app.system_bypass',true),'') IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS NOT NULL AND current_setting('app.agent_workspace_id',true)<>w::text
  OR nullif(current_setting('app.agent_actor_id',true),'') IS NOT NULL AND current_setting('app.agent_actor_id',true)<>actor::text
  OR acting IS NOT NULL AND NOT EXISTS(SELECT 1 FROM assistants WHERE workspace_id=w AND id=acting)
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.session_messages'::regclass WHERE r.rolname=session_user
    AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','profile_unavailable');END IF;
 IF (SELECT count(p.oid)=15 AND bool_and(encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=m.digest)
  FROM (VALUES ('application_scope_source_edges(uuid,text,uuid,text)','eb8966087803239c93bcdac1736ba917251adaed34c244feb3f80bc80d2c9077'),
('knowledge_version_source_edges(uuid,text,uuid,text)','f4deb0d7b7ef41db5dc1d2fedabcef545c836b9f8a78f48d55a2c7413e62f1cf'),
('application_scope_source_edges_before_knowledge_versions(uuid,text,uuid,text)','23d72c938e15ccb1877e6deabc9b75cd44c92f2539b0afd1c0456517086d6a03'),
('application_native_source_edges_dispatch(uuid,text,uuid,text)','e8df0ffdc3f459a5c4bbf6be0703d087ca4e02ad8bf04ce0b0e536dbb82566ca'),
('scope_source_ancestors(uuid,text,uuid)','d8e33fb3a66e4318ed159e288c797b6d55759481e1339d4e53c372cb6907e0e8'),
('scope_source_ancestors_before_workflow_run(uuid,text,uuid)','36bdb461a66fb00b81a5f0f6672b48dcc150858328b035b1ba1da0c3ed3715c8'),
('scope_source_ancestors_before_browser_session(uuid,text,uuid)','c5a684292738319265321ce21b76ea01ba775eb216af66ae992c190d39eedc5c'),
('scope_source_ancestors_before_browser_profile(uuid,text,uuid)','6b775f0025f9dc1be7fb3d6f230d7b0dec53dcb68de66e28c2f0c4326c5f9a48'),
('recording_source_read_allowed(uuid,text,uuid)','68dc93ecfee1a416209fc464f4c4e50130f3a1618da988ad8a5daba1df9f93d1'),
('session_recording_read_allowed(uuid)','d23352b30977749dd2dad03504c1dab5cdeb9aa1b2ef11fc79701bd8714e1886'),
('application_session_eval_point_state(uuid,text,uuid,text[],jsonb)','84bb11a613edf6e1fc7a87b06812535e5fe4b15f882f5ef636be2168e71ffa14'),
('application_session_eval_domain(uuid,text,uuid,text[],jsonb)','47d45fe98cde529fd5bf6c01b9f3fc91cf891219aa94a0ade096fd290053911b'),
('application_session_eval_scan(uuid,uuid,text,integer,text[],jsonb,jsonb,jsonb)','8f01ca980231ecab5963092178ec34d322986d6cd3451b2a037bc721721bae18'),
('application_session_query_parent(uuid,uuid)','85393998bba4fe1af647bbfaade0ae59e364081e4bbea4de1e57ccaf86cbd2e1'),
('application_memory_field_keys()','602979c8ba739025a24515a6df7928c83652c5da6dd16084700c060c9d7b7574')) m(signature,digest) LEFT JOIN pg_proc p ON p.oid=to_regprocedure(m.signature)) IS NOT TRUE
 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','source_contract_changed');END IF;
 IF jsonb_typeof(roots) IS DISTINCT FROM 'array' OR jsonb_array_length(roots) NOT BETWEEN 1 AND 4096
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(roots) r WHERE r-ARRAY['kind','id','version']<>'{}'
    OR r->>'kind' NOT IN('application_field','session_message','session_context_revision','workspace_file') OR NOT r ?& ARRAY['kind','id','version'] OR jsonb_typeof(r->'kind')<>'string' OR jsonb_typeof(r->'id')<>'string'
    OR jsonb_typeof(r->'version')<>'string' OR length(r->>'version') NOT BETWEEN 1 AND 256)
 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','invalid_roots');END IF;
 SELECT coalesce(jsonb_agg(n ORDER BY public.native_turn_key(n)),'[]') INTO nodes
 FROM(SELECT DISTINCT value||'{"tag":"source"}'::jsonb n FROM jsonb_array_elements(roots)) q;
 frontier:=nodes;
 WHILE jsonb_array_length(frontier)>0 LOOP
  step:=step+1;
  IF step>4096 OR jsonb_array_length(nodes)>4096 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','semantic_node_bound');END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(frontier) n WHERE n->>'tag'='source'
   AND n->>'kind' NOT IN('application_field','application_query_domain','session_message','session_context_revision','workspace_file'))
  THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','unsupported_source_kind');END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(frontier) n JOIN application_query_domains q
   ON n->>'tag'='source' AND n->>'kind'='application_query_domain' AND q.workspace_id=w AND q.id=(n->>'id')::uuid
   WHERE q.type_key IN('session_message','session_message_annotation') AND
    (SELECT count(*) FROM(SELECT 1 FROM session_messages m WHERE m.workspace_id=w
      AND m.session_id=(q.domain->>'sessionId')::uuid AND m.sequence_num<=(q.domain->>'throughSequence')::integer LIMIT 4097) bounded)>4096)
  THEN RETURN jsonb_build_object('eligibleMetadata',false,'reason','selector_candidate_bound');END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]') INTO batch FROM(SELECT * FROM public.native_turn_edges(w,frontier) LIMIT 16385) e;
  IF jsonb_array_length(batch)>16384 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','semantic_edge_bound');END IF;
  SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO edges FROM(SELECT DISTINCT value x FROM jsonb_array_elements(edges||batch)) q;
  IF jsonb_array_length(edges)>16384 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','semantic_edge_bound');END IF;
  SELECT coalesce(jsonb_agg(n ORDER BY public.native_turn_key(n)),'[]') INTO next_nodes FROM(
   SELECT DISTINCT b->'child' n FROM jsonb_array_elements(batch) b
   WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) old WHERE public.native_turn_key(old)=public.native_turn_key(b->'child'))
  ) q;
  nodes:=nodes||next_nodes;frontier:=next_nodes;
 END LOOP;
 -- Include every physical candidate source, not only the original evidence.
 SELECT coalesce(jsonb_agg(n ORDER BY n::text),'[]') INTO privacy_nodes FROM(
  SELECT DISTINCT jsonb_build_object('kind',CASE WHEN n->>'tag'='point' THEN 'session_message' ELSE n->>'kind' END,'id',n->'id') n
  FROM jsonb_array_elements(nodes) n
 ) q;
 privacy_frontier:=privacy_nodes;step:=0;
 WHILE jsonb_array_length(privacy_frontier)>0 LOOP
  step:=step+1;
  IF step>4096 OR jsonb_array_length(privacy_nodes)>4096 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','privacy_node_bound');END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(e)),'[]') INTO batch FROM(SELECT * FROM public.native_turn_privacy_edges(w,privacy_frontier) LIMIT 16385) e;
  SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO privacy_edges FROM(SELECT DISTINCT value x FROM jsonb_array_elements(privacy_edges||batch)) q;
  IF jsonb_array_length(privacy_edges)>16384 THEN RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'reason','privacy_edge_bound');END IF;
  SELECT coalesce(jsonb_agg(n ORDER BY n::text),'[]') INTO next_nodes FROM(
   SELECT DISTINCT b->'child' n FROM jsonb_array_elements(batch) b
   WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(privacy_nodes) old WHERE old=b->'child')
  ) q;
  privacy_nodes:=privacy_nodes||next_nodes;privacy_frontier:=next_nodes;
 END LOOP;
 -- Exact six parent-resolution families, preserving a missing nonnull parent.
 WITH n AS MATERIALIZED(SELECT value FROM jsonb_array_elements(privacy_nodes)), p AS (
 SELECT value node,s.id session_id FROM n JOIN sessions s ON value->>'kind'='session' AND s.workspace_id=w AND s.id=(value->>'id')::uuid
 UNION SELECT value,m.session_id FROM n JOIN session_messages m ON value->>'kind'='session_message' AND m.id=(value->>'id')::uuid
  JOIN sessions s ON s.id=m.session_id AND s.workspace_id=w
 UNION SELECT value,r.session_id FROM n JOIN session_context_scope_revisions r ON value->>'kind'='session_context_revision' AND r.workspace_id=w AND r.id=(value->>'id')::uuid
 UNION SELECT value,s.session_id FROM n JOIN session_state s ON value->>'kind'='session_state' AND s.id=(value->>'id')::uuid
 UNION SELECT value,e.session_id FROM n JOIN episodic_memories e ON value->>'kind'='episodic_memory' AND e.id=(value->>'id')::uuid
 UNION SELECT value,e.session_id FROM n JOIN analytics_events e ON value->>'kind'='feedback_event' AND e.id=(value->>'id')::uuid
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('node',p.node,'sessionId',p.session_id,'exists',s.id IS NOT NULL,
  'held',s.recording_privacy_held,'recordingRevision',s.recording_revision,
  'legacyRecording',s.channel_type='telegram' AND s.anchor_kind='channel' AND s.channel_id ~ '^-[0-9]+(:topic:[0-9]+|:discussion:[0-9]+)?$') ORDER BY p.node::text,p.session_id),'[]')
 INTO privacy_parents FROM p LEFT JOIN sessions s ON s.id=p.session_id;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(privacy_nodes) n WHERE n->>'kind' NOT IN('session','application_field','application_query_domain','session_message','session_context_revision','workspace_file'))
 THEN reasons:=array_append(reasons,'unsupported_versionless_ancestry');END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(privacy_parents) p WHERE p->>'sessionId' IS NOT NULL AND
   (p->>'exists' IS DISTINCT FROM 'true' OR p->>'held' IS DISTINCT FROM 'false' OR p->>'recordingRevision' IS NOT NULL OR p->>'legacyRecording'='true'))
 THEN reasons:=array_append(reasons,'recording_or_held_parent');END IF;
 -- No body/content/name/attachment bytes are read in these metadata relations.
 WITH n AS(SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'tag'='source')
 SELECT coalesce(jsonb_agg(jsonb_build_object('node',n.value,'resource',to_jsonb(r),'observation',to_jsonb(o)) ORDER BY n.value::text),'[]')
 INTO field_metadata FROM n LEFT JOIN application_field_resources r ON r.workspace_id=w AND r.id=(n.value->>'id')::uuid
 LEFT JOIN application_field_observations o ON o.workspace_id=w AND o.resource_id=r.id AND o.version=n.value->>'version'
 WHERE n.value->>'kind'='application_field';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(field_metadata) f WHERE f->>'resource' IS NULL OR f->>'observation' IS NULL
  OR f#>'{resource,origin}' IS DISTINCT FROM '{"kind":"native","moduleKey":"native"}'::jsonb
  OR f#>>'{resource,type_key}' NOT IN('session_message','session_message_annotation','memory')
  OR f#>>'{resource,type_key}'='memory' AND f#>>'{resource,selection}' IS DISTINCT FROM 'query_domain'
  OR f#>>'{resource,selection}' NOT IN('read','query','identity','query_domain') OR f#>>'{resource,selected_version}' IS NOT NULL
  OR jsonb_typeof(f#>'{resource,fields}') IS DISTINCT FROM 'array'
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(f#>'{resource,fields}') k WHERE NOT k=ANY(CASE f#>>'{resource,type_key}'
    WHEN 'session_message' THEN ARRAY['id','role','content','sequenceNum','createdAt','senderUserId','senderAssistantId','channelMessageId','attachments']
    WHEN 'session_message_annotation' THEN ARRAY['id','sequenceNum','topicLabel','topicConfidence','replyToText']
    WHEN 'memory' THEN public.application_memory_field_keys() ELSE '{}'::text[] END)))
 THEN reasons:=array_append(reasons,'unsupported_or_missing_field');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('node',n,'domain',to_jsonb(q)) ORDER BY n::text),'[]') INTO domains
 FROM jsonb_array_elements(nodes) n LEFT JOIN application_query_domains q ON q.workspace_id=w AND q.id=(n->>'id')::uuid
 WHERE n->>'tag'='source' AND n->>'kind'='application_query_domain';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(domains) d WHERE d->>'domain' IS NULL
  OR d#>'{domain,origin}' IS DISTINCT FROM '{"kind":"native","moduleKey":"native"}'::jsonb
  OR d#>>'{domain,type_key}' NOT IN('session_message','session_message_annotation','memory')
  OR d#>>'{domain,identity}' IS DISTINCT FROM d#>>'{node,version}'
  OR CASE WHEN d#>>'{domain,type_key}'='memory' THEN
    d#>>'{domain,domain,kind}' IS DISTINCT FROM 'memory_query_domain_v1'
    OR (d#>'{domain,domain}')-ARRAY['kind','fields','bounds','visibility','includeRetained','candidates','policies']<>'{}'
    OR d#>'{domain,domain,candidates}' IS DISTINCT FROM '[]'::jsonb OR d#>'{domain,domain,policies}' IS DISTINCT FROM '[]'::jsonb
   ELSE d#>>'{domain,domain,kind}' IS DISTINCT FROM 'session_query_domain_v1'
    OR (d#>'{domain,domain}')-ARRAY['kind','sessionId','throughSequence','fields','bounds','visibility','parentFingerprint','candidates','points']<>'{}' END)
 THEN reasons:=array_append(reasons,'unsupported_or_missing_domain');END IF;
 -- Strict empty-Memory cohort only. Absence is established in this same snapshot,
 -- not inferred from source ancestry or a formerly empty saved candidate list.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(field_metadata) f WHERE f#>>'{resource,type_key}'='memory')
 AND(EXISTS(SELECT 1 FROM memories WHERE workspace_id=w)
  OR EXISTS(SELECT 1 FROM application_native_resource_owners WHERE workspace_id=w AND origin='{"kind":"native","moduleKey":"native"}' AND resource_type='memory'))
 THEN reasons:=array_append(reasons,'nonempty_or_owned_memory_cohort');END IF;
 -- Includes an explicit [] for every empty physical selector.
 SELECT coalesce(jsonb_agg(jsonb_build_object('node',d->'node','physical',coalesce((SELECT jsonb_agg(jsonb_build_object(
  'id',m.id,'sequence',m.sequence_num,'scopeVersion',m.scope_version,'head',h.scope_revision_id) ORDER BY m.sequence_num,m.id)
  FROM session_messages m LEFT JOIN session_message_annotation_heads h ON h.workspace_id=w AND h.session_id=m.session_id AND h.message_id=m.id
  WHERE m.workspace_id=w AND m.session_id=(d#>>'{domain,domain,sessionId}')::uuid
   AND m.sequence_num<=(d#>>'{domain,domain,throughSequence}')::integer),'[]'::jsonb)) ORDER BY (d->'node')::text),'[]')
 INTO candidates FROM jsonb_array_elements(domains) d WHERE d->>'domain' IS NOT NULL;
 SELECT coalesce(jsonb_agg(jsonb_build_object('node',n,'exists',m.id IS NOT NULL,'sessionId',m.session_id,'sequence',m.sequence_num,
  'scopeVersion',m.scope_version,'head',h.scope_revision_id,'revision',CASE WHEN r.id IS NULL THEN NULL ELSE jsonb_build_object(
   'id',r.id,'sessionId',r.session_id,'parentKind',r.parent_kind,'parentId',r.parent_id,'scopeVersion',r.scope_version,'held',r.scope_held,
   'contentPresent',EXISTS(SELECT 1 FROM session_context_revision_contents c WHERE c.workspace_id=w AND c.revision_id=r.id)) END) ORDER BY n::text),'[]')
 INTO point_metadata FROM jsonb_array_elements(nodes) n LEFT JOIN session_messages m ON m.workspace_id=w AND m.id=(n->>'id')::uuid
 LEFT JOIN session_message_annotation_heads h ON h.workspace_id=w AND h.session_id=m.session_id AND h.message_id=m.id
 LEFT JOIN session_context_scope_revisions r ON r.workspace_id=w AND r.id=h.scope_revision_id
 WHERE n->>'tag'='point';
 WITH n AS(SELECT value FROM jsonb_array_elements(nodes) WHERE value->>'tag'='source'), rows AS(
 SELECT value node,jsonb_build_object('exists',m.id IS NOT NULL,'id',m.id,'sessionId',m.session_id,'sequence',m.sequence_num,
  'workspaceId',m.workspace_id,'userId',m.user_id,'assistantId',m.assistant_id,'version',m.scope_version,'held',m.scope_held,
  'sensitivity',m.sensitivity,'compartments',m.compartments,'projectIds',m.project_ids) metadata
 FROM n LEFT JOIN session_messages m ON m.workspace_id=w AND m.id=(value->>'id')::uuid WHERE value->>'kind'='session_message'
 UNION ALL SELECT value,jsonb_build_object('exists',r.id IS NOT NULL,'id',r.id,'sessionId',r.session_id,'parentId',r.parent_id,'parentKind',r.parent_kind,
  'workspaceId',r.workspace_id,'userId',r.user_id,'assistantId',r.assistant_id,'version',r.scope_version,'held',r.scope_held,
  'sensitivity',r.sensitivity,'compartments',r.compartments,'projectIds',r.project_ids,
  'contentPresent',EXISTS(SELECT 1 FROM session_context_revision_contents c WHERE c.workspace_id=w AND c.revision_id=r.id))
 FROM n LEFT JOIN session_context_scope_revisions r ON r.workspace_id=w AND r.id=(value->>'id')::uuid WHERE value->>'kind'='session_context_revision'
 UNION ALL SELECT value,jsonb_build_object('exists',f.id IS NOT NULL,'id',f.id,'workspaceId',f.workspace_id,'userId',f.user_id,'assistantId',f.assistant_id,
  'version',f.scope_version,'held',f.scope_held,'sensitivity',f.sensitivity,'compartments',f.compartments,'projectIds',f.project_ids,
  'validTo',f.valid_to,'retractedAt',f.retracted_at,'supersededBy',f.superseded_by,'purpose',f.purpose,'hasDerivation',EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind='workspace_file' AND d.resource_id=f.id))
 FROM n LEFT JOIN workspace_files f ON f.workspace_id=w AND f.id=(value->>'id')::uuid WHERE value->>'kind'='workspace_file'
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('node',node,'metadata',metadata) ORDER BY node::text),'[]') INTO native_metadata FROM rows;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(native_metadata) n WHERE n#>>'{metadata,exists}' IS DISTINCT FROM 'true'
  OR n#>>'{node,kind}'='session_context_revision' AND(n#>>'{metadata,parentKind}' IS DISTINCT FROM 'message_annotation' OR n#>>'{metadata,version}' IS DISTINCT FROM '1' OR n#>>'{metadata,contentPresent}' IS DISTINCT FROM 'true')
  OR n#>>'{node,kind}'='workspace_file' AND(n#>>'{metadata,purpose}'='engineering_archive' OR n#>>'{metadata,hasDerivation}'='true'
   OR EXISTS(SELECT 1 FROM workspace_file_session_bindings b WHERE b.file_id=(n#>>'{node,id}')::uuid)
   OR EXISTS(SELECT 1 FROM office_generation_file_bindings b WHERE b.file_id=(n#>>'{node,id}')::uuid)))
 THEN reasons:=array_append(reasons,'unsupported_native_metadata');END IF;
 WITH ids AS(
 SELECT (p->>'sessionId')::uuid id FROM jsonb_array_elements(privacy_parents) p WHERE p->>'sessionId' IS NOT NULL
 UNION SELECT (d#>>'{domain,domain,sessionId}')::uuid FROM jsonb_array_elements(domains) d WHERE d#>>'{domain,domain,sessionId}' IS NOT NULL
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('id',i.id,'exists',s.id IS NOT NULL,'workspaceId',s.workspace_id,'assistantId',s.assistant_id,
  'userId',s.user_id,'visibility',s.visibility,'anchorKind',s.anchor_kind,'anchorRef',s.anchor_ref,'mode',s.mode,'channelType',s.channel_type,
  'channelId',s.channel_id,'appId',s.app_id,'contextGroupId',s.context_group_id,'contextProjectId',s.context_project_id,
  'contextCompartments',s.context_compartments,'effectiveClearance',s.effective_clearance,'recordingHeld',s.recording_privacy_held) ORDER BY i.id),'[]')
 INTO parents FROM ids i LEFT JOIN sessions s ON s.id=i.id;
 SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.id),'[]') INTO derivations FROM scope_derivations d
 WHERE d.workspace_id=w AND EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>'tag'='source' AND n->>'kind'=d.resource_kind AND (n->>'id')::uuid=d.resource_id);
 -- Linear graph operations after source-key materialization; cycles fall back.
 order_json:=public.native_turn_topology(nodes,edges);
 IF order_json IS NULL THEN reasons:=array_append(reasons,'semantic_cycle');END IF;
 context:=jsonb_build_object('workspaceId',w,'actor',actor,'actingAssistant',acting,'sessionUser',session_user,
  'settings',(SELECT jsonb_object_agg(k,current_setting(k,true)) FROM unnest(ARRAY[
  'app.current_user_id','app.agent_actor_id','app.agent_workspace_id','app.agent_clearance','app.agent_compartments',
  'app.agent_project_ids','app.agent_visibility_assistants','app.agent_shared_audience','app.v2_active','app.v2_assistant_id',
  'app.v2_binding','app.v2_cap','app.v2_context_department','app.application_id','app.public_share_root','app.system_bypass']) k));
 locks:=jsonb_build_object('workspace',w,'actor',actor,'actingAssistant',acting,
  'sessions',(SELECT coalesce(jsonb_agg(p->'id' ORDER BY p->>'id'),'[]') FROM jsonb_array_elements(parents) p),
  'nativeRows',(SELECT coalesce(jsonb_agg(jsonb_build_object('kind',n#>'{node,kind}','id',n#>'{node,id}') ORDER BY (n->'node')::text),'[]') FROM jsonb_array_elements(native_metadata) n),
  'note','Metadata discovery only. Host must apply canonical workspace/member/assistant/session/team/project/source lock order, then rerun and prove coverage.');
 counts:=jsonb_build_object('semanticNodes',jsonb_array_length(nodes),'semanticEdges',jsonb_array_length(edges),'privacyNodes',jsonb_array_length(privacy_nodes),
  'privacyEdges',jsonb_array_length(privacy_edges),'points',jsonb_array_length(point_metadata),'domains',jsonb_array_length(domains));
 witness:=jsonb_build_object('context',context,'nodes',(SELECT jsonb_agg(n ORDER BY public.native_turn_key(n)) FROM jsonb_array_elements(nodes) n),
  'edges',edges,'nativeMetadata',native_metadata,'fieldMetadata',field_metadata,'domains',domains,'candidates',candidates,
  'pointMetadata',point_metadata,'memoryPhysicalEmpty',NOT EXISTS(SELECT 1 FROM memories WHERE workspace_id=w),
  'memoryOwnerAbsent',NOT EXISTS(SELECT 1 FROM application_native_resource_owners WHERE workspace_id=w AND origin='{"kind":"native","moduleKey":"native"}' AND resource_type='memory'),'privacyNodes',(SELECT jsonb_agg(n ORDER BY n::text) FROM jsonb_array_elements(privacy_nodes) n),
  'privacyEdges',privacy_edges,'privacyParents',privacy_parents,'sessionParents',parents,'derivations',derivations);
 RETURN jsonb_build_object('eligibleMetadata',cardinality(reasons)=0,'authorizationEvaluated',false,'payloadSelected',false,
  'reasons',to_jsonb(reasons),'counts',counts,'lockPlan',locks,'evaluationOrder',order_json,'witness',witness,'observedAt',statement_timestamp());
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN
 RETURN jsonb_build_object('eligibleMetadata',false,'authorizationEvaluated',false,'payloadSelected',false,'reason','malformed_metadata');
END $body$;
REVOKE ALL ON FUNCTION public.native_turn_metadata_acquire(uuid,jsonb) FROM PUBLIC;
-- No grants, role changes, queries, writes or model calls are executed by this file.


-- Definition fingerprints are metadata, never cached permission results.
CREATE TABLE native_turn_contract_helpers(signature text PRIMARY KEY,fingerprint text NOT NULL);
ALTER TABLE native_turn_contract_helpers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON native_turn_contract_helpers FROM PUBLIC,app_user;
CREATE FUNCTION native_turn_helpers_current() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM pg_class relation WHERE relation.oid='native_turn_contract_helpers'::regclass
  AND relation.relkind='r' AND relation.relpersistence='p' AND relation.relrowsecurity AND NOT relation.relforcerowsecurity
  AND relation.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user)
  AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(relation.relacl,acldefault('r',relation.relowner))) a
   WHERE a.grantee<>relation.relowner OR a.grantor<>relation.relowner)
  AND NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=relation.oid)
  AND(SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid=relation.oid AND attnum>0 AND NOT attisdropped)=ARRAY['signature','fingerprint'])
 AND count(*)>0 AND bool_and(p.oid IS NOT NULL AND h.fingerprint=encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex'))
 FROM native_turn_contract_helpers h LEFT JOIN pg_proc p ON p.oid=to_regprocedure(h.signature)
$$;


CREATE FUNCTION native_turn_parent(w uuid,s uuid,frame jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF frame->>'workspaceId' IS DISTINCT FROM w::text OR NOT coalesce(frame#>'{context,parents}' ? s::text,false) THEN
  RAISE EXCEPTION 'native_turn_requirement_unresolved' USING ERRCODE='PNT01';END IF;
 RETURN frame#>ARRAY['context','parents',s::text];
END $$;
CREATE FUNCTION native_turn_completed_point(w uuid,t text,i uuid,fields text[],memo jsonb,frame jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE k text:=jsonb_build_array(t,i,fields)::text;
BEGIN
 IF frame->>'workspaceId' IS DISTINCT FROM w::text OR NOT coalesce(frame->'points' ? k,false) THEN
  RAISE EXCEPTION 'native_turn_requirement_unresolved' USING ERRCODE='PNT01';END IF;
 RETURN jsonb_build_object('value',frame#>ARRAY['points',k]);
END $$;
CREATE FUNCTION native_turn_completed_scope(w uuid,k text,i uuid,v text,memo jsonb,frame jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF frame->>'workspaceId' IS DISTINCT FROM w::text OR frame#>>ARRAY['scopes',k||':'||i||':'||v] IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION 'native_turn_requirement_unresolved' USING ERRCODE='PNT01';END IF;
 RETURN '{"value":true}'::jsonb;
END $$;
CREATE FUNCTION native_turn_completed_field(w uuid,i uuid,v text,memo jsonb,frame jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE k text:=i||':'||v;
BEGIN
 IF frame->>'workspaceId' IS DISTINCT FROM w::text OR NOT coalesce(frame->'fields' ? k,false) THEN
  RAISE EXCEPTION 'native_turn_requirement_unresolved' USING ERRCODE='PNT01';END IF;
 RETURN jsonb_build_object('value',frame#>ARRAY['fields',k]);
END $$;

CREATE OR REPLACE FUNCTION public.native_turn_read_point(w uuid, t text, i uuid, fields text[], memo jsonb, worklist_frame jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE m session_messages;revision session_context_scope_revisions;source jsonb;parent jsonb;payload jsonb;values_json jsonb;selected jsonb;
 keys text[]:=application_session_field_keys(t);record_version text;source_kind text;source_id uuid;checked jsonb;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 direct_kinds text[];direct_ids uuid[];direct_versions text[];direct_position integer;history_shape boolean:=false;
 dependency record;admitted jsonb;projection jsonb;label jsonb;seen jsonb:='[]';immutable_scope jsonb;
BEGIN
 -- Recording privacy admission precedes body selection.
 IF NOT coalesce(worklist_frame->'privacyCovered' ? ('session_message:'||i),false) THEN RETURN '{}'::jsonb;END IF;
 IF keys IS NULL OR fields IS NULL OR cardinality(fields)>cardinality(keys) OR NOT fields<@keys
  OR array_position(fields,NULL) IS NOT NULL OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f)
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL THEN RETURN NULL;END IF;
 -- Only immutable identity/scope metadata is selected before source admission.
 SELECT id,workspace_id,session_id,scope_version,sequence_num INTO m.id,m.workspace_id,m.session_id,m.scope_version,m.sequence_num
  FROM session_messages WHERE workspace_id=w AND id=i;
 IF NOT FOUND THEN RETURN NULL;END IF;
 parent:=native_turn_parent(w,m.session_id,worklist_frame);IF parent IS NULL THEN RETURN NULL;END IF;
 IF t='session_message' THEN
  source:=worklist_frame#>ARRAY['currents','session_message:'||i,'source'];
  IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' OR source->>'version' IS DISTINCT FROM m.scope_version::text
    THEN RETURN NULL;END IF;

  checked:=native_turn_completed_scope(w,'session_message',i,m.scope_version::text,memo,worklist_frame);
  IF checked->>'value' IS DISTINCT FROM 'true' THEN RETURN NULL;END IF;
  IF clock_timestamp()>=(worklist_frame->>'validUntil')::timestamptz THEN RAISE EXCEPTION 'native_turn_policy_expired' USING ERRCODE='42501';END IF;
  SELECT jsonb_build_object('id',id,'role',role,'content',content,'sequenceNum',sequence_num,'createdAt',created_at,
   'senderUserId',sender_user_id,'senderAssistantId',sender_assistant_id,'channelMessageId',channel_message_id,'attachments',attachments) INTO values_json
   FROM session_messages WHERE workspace_id=w AND id=i AND scope_version=m.scope_version;
  IF values_json IS NULL THEN RETURN NULL;END IF;
  source_kind:='session_message';source_id:=i;
  -- Selected payload changes remain distinct even when an old native writer
  -- changed text without advancing its scope envelope version.
  record_version:=m.scope_version::text||':'||application_field_digest(values_json);
 ELSE
  SELECT r.* INTO revision FROM session_message_annotation_heads h JOIN session_context_scope_revisions r
   ON r.workspace_id=h.workspace_id AND r.id=h.scope_revision_id
   WHERE h.workspace_id=w AND h.session_id=m.session_id AND h.message_id=i AND r.parent_kind='message_annotation'
    AND r.parent_id=i AND r.session_id=m.session_id;
  IF NOT FOUND THEN RETURN NULL;END IF;
  checked:=native_turn_completed_scope(w,'session_context_revision',revision.id,'1',memo,worklist_frame);memo:=coalesce(checked->'memo',memo);
  IF checked->>'value' IS DISTINCT FROM 'true' THEN RETURN '{}'::jsonb;END IF;
  
  IF memo->'nativeWorklist'='true'::jsonb AND revision.scope_version=1
   AND worklist_frame->>'workspaceId'=w::text AND worklist_frame->>'closed'='true'
   AND worklist_frame->'edges' ? ('session_context_revision:'||revision.id||':1')
   AND worklist_frame#>>ARRAY['currents','session_context_revision:'||revision.id,'source','version']='1' THEN
   -- The revision can depend on recording parents absent from the message's
   -- own closure. Its complete current privacy check still precedes payload.
   IF NOT coalesce(worklist_frame->'privacyCovered' ? ('session_context_revision:'||revision.id),false)
    OR revision.scope_held OR scope_review_state_held('session_context_revision',revision.id)
    THEN RETURN NULL;END IF;
   source:=worklist_frame#>ARRAY['currents','session_context_revision:'||revision.id,'source'];
   -- Parent-message source admission is reused only inside this closed proof.
   -- The worker independently rereads the complete canonical revision source
   -- and compares all native sources, graph and context before returning.
  ELSE
   RAISE EXCEPTION 'native_turn_requirement_unresolved' USING ERRCODE='PNT01';
  END IF;

  IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' THEN RETURN NULL;END IF;
  IF clock_timestamp()>=(worklist_frame->>'validUntil')::timestamptz THEN RAISE EXCEPTION 'native_turn_policy_expired' USING ERRCODE='42501';END IF;
  SELECT content INTO payload FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=revision.id;
  IF payload IS NULL THEN RETURN NULL;END IF;
  values_json:=jsonb_build_object('id',i,'sequenceNum',m.sequence_num,'topicLabel',payload->'topicLabel',
   'topicConfidence',payload->'topicConfidence','replyToText',payload->'replyToText');
  source_kind:='session_context_revision';source_id:=revision.id;record_version:=revision.id::text;
 END IF;
 SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO selected FROM jsonb_each(values_json) WHERE key=ANY(fields);
 RETURN jsonb_build_object('value',jsonb_build_object('values',selected,'source',source,'recordVersion',record_version,
  'sourceKind',source_kind,'sourceId',source_id,'sourceVersion',source->>'version','ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','session_field_v1','type',t,'fields',fields)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','session_field_v1','parent',parent->'fingerprint','fields',fields)),
  'references','[]'::jsonb));
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_reduce_scan(w uuid, s uuid, t text, through integer, fields text[], bounds jsonb, visibility jsonb, memo jsonb, worklist_frame jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE candidate record;result jsonb;point jsonb;parent jsonb;candidates jsonb:='[]';points jsonb:='[]';policies jsonb:='[]';children jsonb:='[]';attempts integer:=0;
BEGIN
 parent:=native_turn_parent(w,s,worklist_frame);
 IF parent IS NULL OR through IS NULL OR through<0 OR application_session_field_keys(t) IS NULL OR fields IS NULL
  OR NOT fields<@application_session_field_keys(t) OR array_position(fields,NULL) IS NOT NULL
  OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f)
  OR application_query_scope_valid(bounds) IS NOT TRUE OR jsonb_typeof(visibility) IS DISTINCT FROM 'object'
  OR visibility-ARRAY['userId','assistants']<>'{}' OR NOT visibility ?& ARRAY['userId','assistants'] THEN RETURN '{}'::jsonb;END IF;
 FOR candidate IN SELECT id,sequence_num FROM session_messages WHERE workspace_id=w AND session_id=s AND sequence_num<=through ORDER BY sequence_num,id LOOP
  attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION 'query_domain_complexity_unavailable' USING ERRCODE='42501';END IF;
  result:=native_turn_reduce_envelope(w,t,candidate.id,'query',fields,memo,worklist_frame);memo:=coalesce(result->'memo',memo);point:=result->'value';
  IF point IS NULL OR point='null'::jsonb OR application_query_scope_admits_point(bounds,point->'source') IS NOT TRUE
   OR point#>>'{source,userId}' IS NOT NULL AND point#>>'{source,userId}' IS DISTINCT FROM visibility->>'userId'
   OR point#>>'{source,assistantId}' IS NOT NULL AND visibility->'assistants'<>'null'::jsonb
    AND NOT coalesce(visibility->'assistants' ? (point#>>'{source,assistantId}'),false) THEN CONTINUE;END IF;
  candidates:=candidates||jsonb_build_array(jsonb_build_object('id',candidate.id,'version',point#>'{state,recordVersion}'));
  points:=points||jsonb_build_array(jsonb_build_object('id',candidate.id,'version',point#>'{state,recordVersion}','fields',fields,'source',point->'source'));
  policies:=policies||jsonb_build_array(jsonb_build_object('id',candidate.id,'policy',point#>'{state,policyVersion}'));
  children:=children||jsonb_build_array(point);
 END LOOP;
 RETURN jsonb_build_object('value',jsonb_build_object('parent',parent,'candidates',candidates,'points',points,'policies',policies),'children',children);
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_reduce_domain(w uuid, t text, i uuid, fields text[], memo jsonb, worklist_frame jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE frozen application_query_domains;parent jsonb;current_bounds jsonb;visibility jsonb;result jsonb;scanned jsonb;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;state jsonb;
BEGIN
 SELECT * INTO frozen FROM application_query_domains WHERE workspace_id=w AND id=i AND origin='{"kind":"native","moduleKey":"native"}' AND type_key=t;
 IF NOT FOUND OR frozen.domain->>'kind' IS DISTINCT FROM 'session_query_domain_v1'
  OR frozen.domain-ARRAY['kind','sessionId','throughSequence','fields','bounds','visibility','parentFingerprint','candidates','points']<>'{}'
  OR frozen.domain->'fields' IS DISTINCT FROM to_jsonb(fields) THEN RETURN '{}'::jsonb;END IF;
 parent:=native_turn_parent(w,(frozen.domain->>'sessionId')::uuid,worklist_frame);
 IF parent IS NULL OR parent->'fingerprint' IS DISTINCT FROM frozen.domain->'parentFingerprint' THEN RETURN '{}'::jsonb;END IF;
 current_bounds:=native_turn_session_bounds(w,parent);
 IF current_bounds IS NULL OR application_query_scope_union_contains(frozen.domain->'bounds',jsonb_build_array(current_bounds),4096)->>'contains' IS DISTINCT FROM 'true' THEN RETURN '{}'::jsonb;END IF;
 visibility:=jsonb_build_object('userId',CASE WHEN current_setting('app.agent_shared_audience',true)='true' THEN NULL ELSE actor END,
  'assistants',coalesce(nullif(current_setting('app.agent_visibility_assistants',true),'')::jsonb,'null'::jsonb));
 IF frozen.domain#>>'{visibility,userId}' IS NOT NULL AND frozen.domain#>>'{visibility,userId}' IS DISTINCT FROM visibility->>'userId'
  OR visibility->'assistants'<>'null'::jsonb AND (frozen.domain#>'{visibility,assistants}'='null'::jsonb
   OR NOT coalesce(frozen.domain#>'{visibility,assistants}'<@(visibility->'assistants'),false)) THEN RETURN '{}'::jsonb;END IF;
 result:=native_turn_reduce_scan(w,(frozen.domain->>'sessionId')::uuid,t,(frozen.domain->>'throughSequence')::integer,fields,frozen.domain->'bounds',frozen.domain->'visibility',memo,worklist_frame);
 memo:=coalesce(result->'memo',memo);scanned:=result->'value';
 IF scanned IS NULL OR scanned->'candidates' IS DISTINCT FROM frozen.domain->'candidates' OR scanned->'points' IS DISTINCT FROM frozen.domain->'points' THEN RETURN '{}'::jsonb;END IF;
 state:=jsonb_build_object('values','{}'::jsonb,'source',parent->'scope','recordVersion','1',
  'sourceKind','application_query_domain','sourceId',i,'sourceVersion',frozen.identity,'ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','session_query_domain_v1','identity',frozen.identity,'fields',fields)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','session_query_domain_v1','identity',frozen.identity,'policies',scanned->'policies')),
  'references','[]'::jsonb,'queryPoints',frozen.domain->'points');
 RETURN jsonb_build_object('value',state,'memo',memo,'children',result->'children');
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_reduce_envelope(w uuid, t text, i uuid, selection text, fields text[], memo jsonb, worklist_frame jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE result jsonb;state jsonb;scope jsonb;identity_value text;resource uuid;version_value text;sources jsonb:='[]';children jsonb:='[]';child jsonb;external record;keys text[];
 origin constant jsonb:='{"kind":"native","moduleKey":"native"}';
BEGIN
 IF (t NOT IN('session_message','session_message_annotation') AND NOT(t='memory' AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false))) OR selection NOT IN('read','query','identity','query_domain') THEN RETURN '{}'::jsonb;END IF;
 keys:=ARRAY(SELECT DISTINCT key FROM unnest(fields) key ORDER BY key);
 IF fields IS NULL OR cardinality(keys)<>cardinality(fields) THEN RETURN '{}'::jsonb;END IF;
 IF t='memory' THEN
  IF selection IS DISTINCT FROM 'query_domain' THEN RAISE EXCEPTION 'native_turn_family_unsupported' USING ERRCODE='PNT01';END IF;
  state:=native_turn_empty_memory_domain(w,i,keys,memo->'memoryStatement');
  IF state IS NULL THEN RETURN '{}'::jsonb;END IF;
  RETURN jsonb_build_object('value',native_turn_empty_memory_envelope(w,origin,t,i,selection,NULL,keys,0,state));
 END IF;
 IF selection='query_domain' THEN result:=native_turn_reduce_domain(w,t,i,keys,memo,worklist_frame);children:=coalesce(result->'children','[]'::jsonb);
 ELSE result:=native_turn_completed_point(w,t,i,keys,memo,worklist_frame);END IF;
 memo:=coalesce(result->'memo',memo);state:=result->'value';
 IF state IS NULL OR state='null'::jsonb THEN RETURN '{}'::jsonb;END IF;
 scope:=jsonb_build_object('workspaceId',w,'userId',state#>'{source,userId}','assistantId',state#>'{source,assistantId}',
  'sensitivity',state#>'{source,sensitivity}','compartments',state#>'{source,compartments}','projectIds',state#>'{source,projectIds}');
 IF entity_derivation_envelope_valid(scope) IS NOT TRUE THEN RETURN '{}'::jsonb;END IF;
 identity_value:=application_field_digest(jsonb_build_object('workspaceId',w,'origin',origin,'typeKey',t,'id',i,
  'selection',selection,'selectedVersion',NULL,'fields',keys,'fieldIdentity',state->'fieldIdentity'));
 resource:=application_field_resource_uuid(identity_value);
 -- Metadata eligibility proved a closed graph with no independent sources.
 IF worklist_frame->>'workspaceId' IS DISTINCT FROM w::text OR worklist_frame->>'closed' IS DISTINCT FROM 'true'
  OR NOT coalesce(worklist_frame->'sourceKeys' ? ((state->>'sourceKind')||':'||(state->>'sourceId')||':'||(state->>'sourceVersion')),false)
 THEN RAISE EXCEPTION 'native_turn_requirement_unresolved' USING ERRCODE='PNT01';END IF;
 FOR child IN SELECT value FROM jsonb_array_elements(children) LOOP
  sources:=sources||jsonb_build_array(child->'source')||coalesce(child->'sources','[]');
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') INTO sources FROM (SELECT DISTINCT value FROM jsonb_array_elements(sources)) unique_sources;
 IF jsonb_array_length(sources)>4096 OR jsonb_array_length(children)>4096 THEN RETURN '{}'::jsonb;END IF;
 version_value:=application_field_digest(jsonb_build_object('resourceId',resource,'recordVersion',state->'recordVersion',
  'sourceVersion',state->'sourceVersion','policyVersion',state->'policyVersion','scope',scope,'sources',sources));
 RETURN jsonb_build_object('value',jsonb_build_object('resourceId',resource,'identity',identity_value,'origin',origin,'typeKey',t,'id',i,
  'selection',selection,'selectedVersion',NULL,'fields',keys,'fieldIdentity',state->'fieldIdentity','state',state,'children',children,'sources',sources,
  'source',scope||jsonb_build_object('resourceKind','application_field','resourceId',resource,'version',version_value)));
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_reduce_field(w uuid, i uuid, v text, memo jsonb, worklist_frame jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE key text:='field:'||i||':'||v;resource application_field_resources;observation application_field_observations;result jsonb;envelope jsonb;current_source jsonb;dependency record;refs jsonb:='[]';empty_capture jsonb;empty_lineage jsonb;empty_entry jsonb;
BEGIN
 IF scope_review_state_held('application_field',i) THEN RETURN NULL;END IF;
 SELECT * INTO resource FROM application_field_resources WHERE workspace_id=w AND id=i;
 IF NOT FOUND THEN RETURN '{}'::jsonb;END IF;
 IF resource.origin<>'{"kind":"native","moduleKey":"native"}'::jsonb OR (resource.type_key NOT IN('session_message','session_message_annotation') AND NOT(resource.type_key='memory' AND coalesce(memo#>>'{memoryStatement,workspaceId}'=w::text,false))) THEN
  RAISE EXCEPTION 'native_turn_family_unsupported' USING ERRCODE='PNT01';
 END IF;
 IF EXISTS(SELECT 1 FROM pg_roles role JOIN pg_class tab ON tab.oid='session_messages'::regclass WHERE role.rolname=session_user
  AND (role.rolsuper OR role.rolbypassrls OR pg_has_role(role.oid,tab.relowner,'USAGE'))) THEN RETURN '{}'::jsonb;END IF;
 SELECT * INTO observation FROM application_field_observations WHERE workspace_id=w AND resource_id=i AND version=v;
 IF NOT FOUND OR resource.selected_version IS NOT NULL THEN RETURN '{}'::jsonb;END IF;

 result:=native_turn_reduce_envelope(w,resource.type_key,resource.resource_id,resource.selection,resource.fields,memo,worklist_frame);
 memo:=coalesce(result->'memo',memo);envelope:=result->'value';
 IF envelope IS NULL OR envelope->>'identity' IS DISTINCT FROM resource.identity OR (envelope#>>'{state,policyVersion}' IS DISTINCT FROM observation.policy_version
   AND NOT coalesce(resource.origin='{"kind":"native","moduleKey":"native"}'::jsonb AND resource.type_key='memory'
    AND envelope#>>'{state,legacyPolicyVersion}'=observation.policy_version,false))
  OR workflow_evidence_envelope_visible(w,observation.source_scope) IS NOT TRUE OR workflow_evidence_envelope_visible(w,envelope->'source') IS NOT TRUE THEN RETURN '{}'::jsonb;END IF;
 FOR dependency IN SELECT * FROM application_field_observation_sources WHERE workspace_id=w AND resource_id=i AND version=v ORDER BY source_kind,source_id,source_version LOOP
  IF dependency.source_kind='application_field' THEN
   result:=native_turn_completed_field(w,dependency.source_id,dependency.source_version,memo,worklist_frame);memo:=coalesce(result->'memo',memo);current_source:=result->'value';
  ELSE RAISE EXCEPTION 'native_turn_family_unsupported' USING ERRCODE='PNT01';END IF;
  IF current_source IS NULL OR current_source->>'held' IS DISTINCT FROM 'false'
   OR dependency.source_kind='external_source' AND current_source->>'version' IS DISTINCT FROM dependency.source_version THEN RETURN '{}'::jsonb;END IF;
 END LOOP;
 current_source:=(envelope->'source')||jsonb_build_object('held',false,'validTo',NULL,'retractedAt',NULL);
 RETURN jsonb_build_object('value',current_source);
END $function$
;

DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('session_context_parent_snapshot(uuid,uuid)')) IS DISTINCT FROM '1a0e396933986f7668047dada63e1a2add9ba7b53887334d25bb3a3dc74a4f3c' THEN RAISE EXCEPTION 'Native turn prerequisite changed: session_context_parent_snapshot';END IF;END $$;
