DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('application_principal_query_bounds(uuid,uuid,boolean)')) IS DISTINCT FROM '7387acc411884780cdaeea9fb30787bbae2205252582dd1fe636f9d2a4403cdd' THEN RAISE EXCEPTION 'Native turn prerequisite changed: application_principal_query_bounds';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('application_native_query_bounds(uuid)')) IS DISTINCT FROM '4b53d101c72abb90d3111a31a225caddb80795c303390678ad53b48f36abbf22' THEN RAISE EXCEPTION 'Native turn prerequisite changed: application_native_query_bounds';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('application_session_query_bounds(uuid,jsonb)')) IS DISTINCT FROM 'cdcf2c6726be3b8a82e569fe8d2012b1a1d15030048d43a391ee72502328ca8b' THEN RAISE EXCEPTION 'Native turn prerequisite changed: application_session_query_bounds';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('application_memory_query_context(uuid)')) IS DISTINCT FROM '01005c743471b53304ef3b6c2b5154f67961231496c4be53e24b85cbce3f93bd' THEN RAISE EXCEPTION 'Native turn prerequisite changed: application_memory_query_context';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('application_memory_statement_domain(uuid,uuid,text[],jsonb)')) IS DISTINCT FROM '53238a157b0def3379c9ae946e47bfc00be6931c2b5807d54c6b3d13882cca4c' THEN RAISE EXCEPTION 'Native turn prerequisite changed: application_memory_statement_domain';END IF;END $$;
DO $$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('application_memory_statement_envelope(uuid,jsonb,text,uuid,text,text,text[],integer,jsonb)')) IS DISTINCT FROM '4779f1dbef9e182105b49b0e18fe4c3d5c226f98e8f4a0c79780f06f52c6815b' THEN RAISE EXCEPTION 'Native turn prerequisite changed: application_memory_statement_envelope';END IF;END $$;
CREATE OR REPLACE FUNCTION public.native_turn_parent_scope(w uuid, i uuid)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE s sessions;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 acting uuid:=nullif(current_setting('app.v2_assistant_id',true),'')::uuid;
 live_floor text;invocation_floor text:=nullif(current_setting('app.agent_clearance',true),'');
BEGIN
 -- Recording privacy admission precedes body selection.
 IF NOT session_recording_read_allowed(i) THEN RETURN NULL;END IF;
 -- There is no application data grant for a raw native session. A canonical
 -- application-session port must be integrated before that lane is available.
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS NOT NULL AND current_setting('app.agent_workspace_id',true)::uuid<>w
  OR nullif(current_setting('app.agent_actor_id',true),'') IS NOT NULL AND current_setting('app.agent_actor_id',true)::uuid<>actor
  OR acting IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM assistants a WHERE a.workspace_id=w AND a.id=acting)
    OR assistant_placement_visible(actor,acting) IS NOT TRUE) THEN RETURN NULL;END IF;
 SELECT id,workspace_id,assistant_id,user_id,visibility,context_group_id,context_project_id,context_compartments,effective_clearance INTO s.id,s.workspace_id,s.assistant_id,s.user_id,s.visibility,s.context_group_id,s.context_project_id,s.context_compartments,s.effective_clearance FROM sessions WHERE workspace_id=w AND id=i;
 IF NOT FOUND OR NOT coalesce(session_personal_audience(s) OR session_workspace_audience(s),false)
  OR session_project_audience(s,false) IS NOT TRUE THEN RETURN NULL;END IF;
 -- Personal sessions inherit a current, persisted assistant/member ceiling.
 -- Shared/legacy unclassified rows remain held. The GUC can only narrow the
 -- real ceiling; it never supplies authority or a missing canonical label.
 live_floor:=s.effective_clearance;
 IF live_floor IS NULL AND s.visibility='personal' THEN
  SELECT CASE WHEN sensitivity_rank(a.clearance)<=sensitivity_rank(wm.clearance) THEN a.clearance ELSE wm.clearance END
   INTO live_floor FROM assistants a JOIN workspace_members wm ON wm.workspace_id=a.workspace_id
   WHERE a.workspace_id=w AND a.id=coalesce(acting,s.assistant_id) AND wm.user_id=actor;
  IF live_floor NOT IN('public','internal','confidential') OR live_floor IS NULL THEN RETURN NULL;END IF;
  IF invocation_floor IS NOT NULL THEN
   IF invocation_floor NOT IN('public','internal','confidential') THEN RETURN NULL;END IF;
   IF sensitivity_rank(invocation_floor)<sensitivity_rank(live_floor) THEN live_floor:=invocation_floor;END IF;
  END IF;
 END IF;
 IF live_floor IS NULL OR s.context_compartments IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('workspaceId',w,'userId',CASE WHEN s.visibility='personal' THEN s.user_id ELSE NULL END,
  'assistantId',NULL,'sensitivity',live_floor,'compartments',s.context_compartments,
  'projectIds',CASE WHEN s.context_project_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(s.context_project_id) END,
  'assistant',s.assistant_id,'createdBy',s.user_id);
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_capture_parent(w uuid, s uuid)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE parent jsonb;binding jsonb;
BEGIN
 parent:=native_turn_parent_scope(w,s);
 IF parent IS NULL OR workflow_evidence_envelope_visible(w,parent) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT jsonb_build_object('id',id,'workspaceId',workspace_id,'assistantId',assistant_id,'userId',user_id,
  'visibility',visibility,'anchorKind',anchor_kind,'anchorRef',anchor_ref,'mode',mode,'channelType',channel_type,
  'channelId',channel_id,'appId',app_id,'contextGroupId',context_group_id,'contextProjectId',context_project_id,
  'contextCompartments',context_compartments,'effectiveClearance',effective_clearance) INTO binding
  FROM sessions WHERE workspace_id=w AND id=s;
 IF binding IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('scope',parent-ARRAY['assistant','createdBy'],'fingerprint',application_field_digest(binding));
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_principal_bounds(w uuid, p_actor uuid, p_release boolean)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE member jsonb; v2 jsonb; scope jsonb; rank int; cap int:=3; teams jsonb; ceiling jsonb; projects jsonb;
 departments jsonb; labels jsonb; others jsonb; binding jsonb; assistant uuid; assistant_cap int; shared_projects jsonb;
BEGIN
 IF p_actor IS NULL OR p_release IS DISTINCT FROM false OR public.agent_visibility_allows(w,NULL,NULL) IS NOT TRUE
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.application_query_domains'::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RETURN NULL; END IF;
 member:=public.member_principal_operation_grants(p_actor,false,w)->w::text;
 IF member IS NULL THEN RETURN NULL; END IF;
 projects:=coalesce(nullif(current_setting('app.agent_project_ids',true),'')::jsonb,'null'::jsonb);
 IF jsonb_typeof(member->'v2')='object' THEN
  v2:=member->'v2';binding:=v2->'k';ceiling:='null';
  IF nullif(current_setting('app.agent_clearance',true),'') IS NOT NULL
   AND current_setting('app.v2_active',true) IS DISTINCT FROM 'true' AND nullif(current_setting('app.v2_assistant_id',true),'') IS NULL THEN
   cap:=public.sensitivity_rank(current_setting('app.agent_clearance',true));
   ceiling:=coalesce(nullif(current_setting('app.agent_compartments',true),'')::jsonb,'[]'::jsonb);
  END IF;
  IF cap IS NULL OR binding IS NULL OR jsonb_typeof(binding) NOT IN('array','null')
   OR jsonb_typeof(ceiling) NOT IN('array','null')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN binding='null' THEN '[]'::jsonb ELSE binding END) item WHERE jsonb_typeof(item)<>'string')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN ceiling='null' THEN '[]'::jsonb ELSE ceiling END) item WHERE jsonb_typeof(item)<>'string') THEN RETURN NULL; END IF;
  IF v2->>'c' IS NOT NULL THEN PERFORM (v2->>'c')::uuid; END IF;
  SELECT coalesce(jsonb_object_agg(key,least((value#>>'{}')::int,cap) ORDER BY key),'{}') INTO departments
   FROM jsonb_each(v2->'d') WHERE (binding='null' OR binding ? key) AND (ceiling='null' OR ceiling ? ('team:'||key)) AND least((value#>>'{}')::int,cap)>0;
  SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO labels FROM (
   SELECT DISTINCT value#>>'{}' AS id FROM jsonb_array_elements((v2->'p')||(v2->'o'))
   WHERE (binding='null' OR binding ? (value#>>'{}')) AND (ceiling='null' OR ceiling ? ('project:'||(value#>>'{}')))) allowed;
  PERFORM key::uuid FROM jsonb_each(departments);
  PERFORM (value#>>'{}')::uuid FROM jsonb_array_elements(labels);
  IF ceiling='null' THEN others:='null';
  ELSE SELECT coalesce(jsonb_agg(value ORDER BY value),'[]') INTO others FROM (
   SELECT DISTINCT value FROM jsonb_array_elements(ceiling) WHERE value#>>'{}' NOT LIKE 'team:%' AND value#>>'{}' NOT LIKE 'project:%') allowed; END IF;
  scope:=jsonb_build_object('kind','native_department_v2','tier',least((v2->>'b')::int,cap),'departments',departments,
   'contextDepartment',v2->'c','projectLabels',labels,'otherLabels',others,'projectIds',projects);
 ELSE
  rank:=(member->>'r')::int;
  IF nullif(current_setting('app.agent_clearance',true),'') IS NOT NULL THEN
   cap:=public.sensitivity_rank(current_setting('app.agent_clearance',true));
   IF cap IS NULL THEN RETURN NULL; END IF;
   rank:=least(rank,cap);
  END IF;
  teams:=public.application_query_set_intersection(member->'c',coalesce(nullif(current_setting('app.agent_compartments',true),'')::jsonb,'null'::jsonb));
  scope:=public.application_normalize_native_query_bounds(jsonb_build_object('kind','native_legacy','tier',rank,'compartments',teams,'projectIds',projects));
 END IF;
 IF scope IS NULL OR public.application_query_scope_cap((scope->>'tier')::int,'null',scope->'projectIds') IS NULL
  OR (SELECT count(*) FROM jsonb_each(CASE WHEN scope->'departments'='null' THEN '{}'::jsonb ELSE scope->'departments' END))>256
  OR jsonb_array_length(scope->'projectLabels')>256 OR scope->'otherLabels'<>'null' AND jsonb_array_length(scope->'otherLabels')>256 THEN RETURN NULL; END IF;
 RETURN scope;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_query_bounds(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
 IF nullif(current_setting('app.application_id',true),'') IS NOT NULL THEN RETURN NULL; END IF;
 RETURN public.native_turn_principal_bounds(w,nullif(current_setting('app.current_user_id',true),'')::uuid,false);
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_session_bounds(w uuid, parent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE bounds jsonb;
BEGIN
 bounds:=native_turn_query_bounds(w);
 IF bounds IS NULL THEN
  -- This is the already-admitted real personal guest session's scope, not
  -- a workspace/General fallback for an unknown principal or missing source.
  IF parent IS NULL OR parent#>>'{scope,userId}' IS DISTINCT FROM nullif(current_setting('app.current_user_id',true),'')
   OR parent#>>'{scope,sensitivity}' IS DISTINCT FROM 'public' THEN RETURN NULL;END IF;
  bounds:=application_query_scope_cap(sensitivity_rank(parent#>>'{scope,sensitivity}'),parent#>'{scope,compartments}',parent#>'{scope,projectIds}');
 END IF;
 IF application_query_scope_valid(bounds) IS NOT TRUE THEN RETURN NULL;END IF;RETURN bounds;
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_empty_memory_context(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;bounds jsonb;policy jsonb;mask jsonb;keys text[];fields jsonb;scope jsonb;
BEGIN
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS DISTINCT FROM w::text
  OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.memories'::regclass WHERE r.rolname=session_user
   AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN RETURN NULL;END IF;
 -- Unsupported in-flight data selectors hold instead of dropping a restriction.
 IF coalesce(nullif(current_setting('app.native_query_data_ceilings',true),'')::jsonb,'[]'::jsonb)<>'[]'::jsonb THEN RETURN NULL;END IF;
 bounds:=native_turn_query_bounds(w);IF bounds IS NULL OR application_query_scope_valid(bounds) IS NOT TRUE THEN RETURN NULL;END IF;
 keys:=ARRAY(SELECT key FROM unnest(application_memory_field_keys()) key ORDER BY key);
 IF EXISTS(SELECT 1 FROM application_native_resource_owners WHERE workspace_id=w AND origin='{"kind":"native","moduleKey":"native"}' AND resource_type='memory') THEN RETURN NULL;END IF;
 policy:='{"registered":false}'::jsonb;
 IF policy->>'registered'='false' THEN
  SELECT jsonb_agg(jsonb_build_object('key',key,'read','[]'::jsonb,'write','[]'::jsonb,'releaseReadTo','[]'::jsonb,'releaseWriteTo','[]'::jsonb) ORDER BY key)
   INTO fields FROM unnest(keys) key;
  -- This is the public schema definition, not a default for a data row or missing ancestor.
  scope:=jsonb_build_object('workspaceId',w,'userId',NULL,'assistantId',NULL,'sensitivity','public','compartments','[]'::jsonb,'projectIds','[]'::jsonb);
  policy:=jsonb_build_object('registered',true,'held',false,'nativeDefault',true,'roleKeys','[]'::jsonb,
   'metadata',jsonb_build_object('moduleKey','native','origin','{"kind":"native","moduleKey":"native"}'::jsonb,'typeKey','memory',
    'schemaVersion','memory-fields-v1','policyVersion','memory-fields-v1','fieldKeys',keys,'fields',fields,'scope',scope),
   'fingerprint',application_field_digest(jsonb_build_object('kind','memory-fields-v1','workspaceId',w,'fields',fields)));
  mask:=application_native_member_field_permissions(w,policy,actor);

 END IF;
 IF workflow_evidence_envelope_visible(w,policy#>'{metadata,scope}') IS NOT TRUE OR jsonb_typeof(mask->'read') IS DISTINCT FROM 'array' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('policy',policy,'read',mask->'read','bounds',bounds,
  'visibility',jsonb_build_object('userId',CASE WHEN current_setting('app.agent_shared_audience',true)='true' THEN NULL ELSE actor END,
   'assistants',coalesce(nullif(current_setting('app.agent_visibility_assistants',true),'')::jsonb,'null'::jsonb)));
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_empty_memory_domain(w uuid, i uuid, fields text[], admitted jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE frozen application_query_domains;context jsonb;scanned jsonb;
BEGIN
 SELECT * INTO frozen FROM application_query_domains WHERE workspace_id=w AND id=i AND origin='{"kind":"native","moduleKey":"native"}' AND type_key='memory';
 IF NOT FOUND OR frozen.domain->>'kind' IS DISTINCT FROM 'memory_query_domain_v1'
  OR frozen.domain-ARRAY['kind','fields','bounds','visibility','includeRetained','candidates','policies']<>'{}'
  OR frozen.domain->'fields' IS DISTINCT FROM to_jsonb(fields) THEN RETURN NULL;END IF;
 context:=admitted->'context';
 IF context IS NULL OR context#>>'{policy,metadata,schemaVersion}' IS DISTINCT FROM frozen.schema_version
  OR NOT coalesce(to_jsonb(fields)<@(context->'read'),false)
  OR application_query_scope_union_contains(frozen.domain->'bounds',jsonb_build_array(context->'bounds'),4096)->>'contains' IS DISTINCT FROM 'true'
  OR frozen.domain->'visibility' IS DISTINCT FROM context->'visibility' THEN RETURN NULL;END IF;
 IF fields IS NULL OR NOT fields<@application_memory_field_keys()
  OR application_query_scope_valid(frozen.domain->'bounds') IS NOT TRUE
  OR jsonb_typeof(frozen.domain->'includeRetained') IS DISTINCT FROM 'boolean'
  OR EXISTS(SELECT 1 FROM memories WHERE workspace_id=w)
  OR EXISTS(SELECT 1 FROM application_native_resource_owners WHERE workspace_id=w AND origin='{"kind":"native","moduleKey":"native"}' AND resource_type='memory') THEN RETURN NULL;END IF;
 scanned:='{"candidates":[],"policies":[]}'::jsonb;
 IF scanned IS NULL OR scanned->'candidates' IS DISTINCT FROM frozen.domain->'candidates' OR scanned->'policies' IS DISTINCT FROM frozen.domain->'policies' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('values','{}'::jsonb,'source',context#>'{policy,metadata,scope}','recordVersion',frozen.schema_version,
  'sourceKind','application_query_domain','sourceId',i,'sourceVersion',frozen.identity,'ownerId',NULL,
  'fieldIdentity',application_field_digest(jsonb_build_object('kind','memory_query_domain_v1','identity',frozen.identity,'fields',fields)),
  'policyVersion',application_field_digest(jsonb_build_object('kind','memory_query_domain_v1','identity',frozen.identity,'policy',context#>'{policy,fingerprint}','policies',scanned->'policies')),
  'references','[]'::jsonb);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.native_turn_empty_memory_envelope(w uuid, p_origin jsonb, p_type text, p_id uuid, p_selection text, p_selected_version text, p_fields text[], depth integer DEFAULT 0, admitted_state jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql STABLE
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE state jsonb; field_keys text[]; identity text; resource uuid; scope jsonb; version text;
 reference jsonb; child jsonb; children jsonb:='[]'; sources jsonb:='[]'; native_source jsonb; external record;
BEGIN
 IF depth NOT BETWEEN 0 AND 2 OR p_origin IS DISTINCT FROM '{"kind":"native","moduleKey":"native"}'::jsonb OR p_type IS DISTINCT FROM 'memory' OR p_selection IS DISTINCT FROM 'query_domain' OR p_selected_version IS NOT NULL OR admitted_state->'references' IS DISTINCT FROM '[]'::jsonb OR admitted_state ? 'queryPoints' THEN RETURN NULL; END IF;
 IF p_origin->>'kind'='generic' THEN p_type:='record.'||(p_origin->>'entityTypeId')::uuid; END IF;
 field_keys:=ARRAY(SELECT DISTINCT field FROM unnest(p_fields) field ORDER BY field);
 IF p_fields IS NULL OR cardinality(field_keys) IS DISTINCT FROM cardinality(p_fields) THEN RETURN NULL; END IF;
 state:=admitted_state;
 IF state IS NULL THEN RETURN NULL; END IF;
 scope:=jsonb_build_object('workspaceId',w,'userId',state#>'{source,userId}','assistantId',state#>'{source,assistantId}',
  'sensitivity',state#>'{source,sensitivity}','compartments',state#>'{source,compartments}','projectIds',state#>'{source,projectIds}');
 IF entity_derivation_envelope_valid(scope) IS NOT TRUE THEN RETURN NULL; END IF;
 identity:=application_field_digest(jsonb_build_object('workspaceId',w,'origin',p_origin,'typeKey',p_type,'id',p_id,
  'selection',p_selection,'selectedVersion',p_selected_version,'fields',field_keys,'fieldIdentity',state->'fieldIdentity'));
 resource:=application_field_resource_uuid(identity);
 version:=application_field_digest(jsonb_build_object('resourceId',resource,'recordVersion',state->'recordVersion',
  'sourceVersion',state->'sourceVersion','policyVersion',state->'policyVersion','scope',scope,'sources',sources));
 RETURN jsonb_build_object('resourceId',resource,'identity',identity,'origin',p_origin,'typeKey',p_type,'id',p_id,
  'selection',p_selection,'selectedVersion',p_selected_version,'fields',field_keys,'fieldIdentity',state->'fieldIdentity',
  'state',state,'children',children,'sources',sources,
  'source',scope||jsonb_build_object('resourceKind','application_field','resourceId',resource,'version',version));
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN NULL;
END $function$
;
CREATE FUNCTION native_turn_context() RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$ SELECT jsonb_build_object('sessionUser',session_user,'currentUser',current_user,'settings',(SELECT jsonb_object_agg(k,current_setting(k,true)) FROM unnest(ARRAY['app.agent_actor_id','app.agent_clearance','app.agent_compartments','app.agent_mutation_compartments','app.agent_project_ids','app.agent_shared_audience','app.agent_visibility_assistants','app.agent_workspace_id','app.application_assistant_id','app.application_command_key','app.application_credential_id','app.application_credential_review_id','app.application_grant_review_id','app.application_home_binding_id','app.application_id','app.application_native_write_intent','app.application_oauth_id','app.application_record_write_type','app.assistant_transfer','app.association_source_membership_actor','app.association_source_order_actor','app.capture_admission','app.capture_session','app.connector_setup_id','app.creation_admission','app.crm_erasure_capture','app.crm_historical_actor','app.current_user_id','app.deployed_application_module','app.engineering_archive_publication','app.explicit_general','app.external_key_explicit','app.external_key_session','app.external_source_action','app.external_source_actor_id','app.external_source_assistant_id','app.external_source_operation_id','app.external_source_service_binding_id','app.knowledge_event_actor','app.media_intake_parent','app.native_entity_write_intent','app.native_query_data_ceilings','app.native_task_write_intent','app.page_event_moved_id','app.pdf_intake_artifact','app.programmatic_candidate','app.programmatic_candidate_source','app.programmatic_publication_batch','app.public_share_mode','app.public_share_root','app.public_share_token_hash','app.recording_session_admission','app.retained_task_goal','app.routine_intake_apply_receipt','app.routine_intake_toggle_receipt','app.scope_review_actor','app.session_creation_admission','app.source_service_release_review_id','app.system_bypass','app.v2_active','app.v2_assistant_id','app.v2_binding','app.v2_cap','app.v2_context_department','app.workflow_schedule_review']::text[]) k)) $$;
-- Typed source capture: only metadata is selected before current policy admission.
CREATE FUNCTION native_turn_capture_sources(w uuid,meta jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 acting uuid:=nullif(current_setting('app.v2_assistant_id',true),'')::uuid;
 member_role text;v2 boolean;n jsonb;m jsonb;source jsonb;parents jsonb;currents jsonb:='{}';parent sessions;projects uuid[];
BEGIN
 SELECT department_read_v2 INTO v2 FROM workspaces WHERE id=w;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT role INTO member_role FROM workspace_members WHERE workspace_id=w AND user_id=actor;
 IF NOT FOUND OR actor IS NULL OR acting IS NOT NULL AND
  (NOT EXISTS(SELECT 1 FROM assistants WHERE workspace_id=w AND id=acting) OR assistant_placement_visible(actor,acting) IS NOT TRUE) THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_object_agg((p->>'id'),native_turn_capture_parent(w,(p->>'id')::uuid)),'{}') INTO parents
 FROM jsonb_array_elements(meta#>'{witness,sessionParents}') p;
 FOR n IN SELECT value FROM(SELECT DISTINCT value FROM jsonb_array_elements(meta#>'{witness,nativeMetadata}')) distinct_nodes
  ORDER BY CASE WHEN value#>>'{node,kind}'='session_context_revision' THEN 1 ELSE 0 END,value::text LOOP
  m:=n->'metadata';
  source:=jsonb_build_object('workspaceId',w,'resourceKind',n#>'{node,kind}','resourceId',n#>'{node,id}',
   'userId',m->'userId','assistantId',m->'assistantId','sensitivity',m->'sensitivity','compartments',m->'compartments','projectIds',m->'projectIds',
   'version',m->>'version','held',m->'held','validTo',m->'validTo','retractedAt',m->'retractedAt');
  IF m->>'exists' IS DISTINCT FROM 'true' OR source->>'held' IS DISTINCT FROM 'false' OR source->>'validTo' IS NOT NULL OR source->>'retractedAt' IS NOT NULL
   OR scope_review_state_held(n#>>'{node,kind}',(n#>>'{node,id}')::uuid)
   OR jsonb_typeof(source->'version') IS DISTINCT FROM 'string' OR length(source->>'version')=0
   OR entity_derivation_envelope_valid(source) IS NOT TRUE
   OR agent_visibility_allows(w,(source->>'userId')::uuid,(source->>'assistantId')::uuid) IS NOT TRUE
   OR workflow_evidence_envelope_visible(w,source) IS NOT TRUE THEN RETURN NULL;END IF;
  IF n#>>'{node,kind}'='session_message' THEN
   SELECT s.id,s.workspace_id,s.visibility,s.user_id,s.context_group_id,s.context_compartments,s.context_project_id,s.effective_clearance
   INTO parent.id,parent.workspace_id,parent.visibility,parent.user_id,parent.context_group_id,parent.context_compartments,parent.context_project_id,parent.effective_clearance FROM sessions s JOIN assistants a ON a.id=s.assistant_id AND a.workspace_id=w
    WHERE s.id=(m->>'sessionId')::uuid AND (s.workspace_id IS NULL OR s.workspace_id=w);
   IF NOT FOUND OR parent.visibility='personal' AND parent.user_id IS DISTINCT FROM actor
    OR parent.visibility='workspace' AND parent.workspace_id IS DISTINCT FROM w
    OR parents->(parent.id::text) IS NULL OR parents->(parent.id::text)='null'::jsonb
    OR parent.context_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workspace_groups
     WHERE id=parent.context_group_id AND workspace_id=w AND kind='team' AND status='active')
    OR workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,
     'userId',CASE WHEN parent.visibility='personal' THEN parent.user_id ELSE NULL END,'assistantId',NULL,
     'sensitivity',coalesce(parent.effective_clearance,'public'),'compartments',coalesce(parent.context_compartments,'{}'::text[]),
     'projectIds',CASE WHEN parent.context_project_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(parent.context_project_id) END)) IS NOT TRUE
    OR parent.visibility='personal' AND source->>'userId' IS DISTINCT FROM parent.user_id::text
    OR NOT(source->'compartments' @> to_jsonb(coalesce(parent.context_compartments,'{}'::text[])))
    OR parent.context_project_id IS NOT NULL AND NOT(source->'projectIds' @> jsonb_build_array(parent.context_project_id)
      OR source->'compartments' @> jsonb_build_array('project:'||parent.context_project_id::text)) THEN RETURN NULL;END IF;
   projects:=ARRAY(SELECT jsonb_array_elements_text(source->'projectIds')::uuid);
   IF parent.context_project_id IS NOT NULL THEN projects:=array_append(projects,parent.context_project_id);END IF;
   IF EXISTS(SELECT 1 FROM unnest(projects) p WHERE NOT EXISTS(SELECT 1 FROM workspace_projects pr
    WHERE pr.workspace_id=w AND pr.id=p AND pr.status='active' AND(v2 OR member_role IN('owner','admin')
     OR EXISTS(SELECT 1 FROM workspace_project_members pm WHERE pm.project_id=p AND pm.user_id=actor)))) THEN RETURN NULL;END IF;
   -- Metadata eligibility rejects every archive and unknown/file-segment ancestor.
  ELSIF n#>>'{node,kind}'='session_context_revision' THEN
   IF m->>'parentKind' IS DISTINCT FROM 'message_annotation' OR m->>'version' IS DISTINCT FROM '1'
    OR m->>'contentPresent' IS DISTINCT FROM 'true' OR parents->(m->>'sessionId') IS NULL OR parents->(m->>'sessionId')='null'::jsonb
    OR NOT EXISTS(SELECT 1 FROM session_messages sm WHERE sm.workspace_id=w AND sm.id=(m->>'parentId')::uuid AND sm.session_id=(m->>'sessionId')::uuid)
    OR currents#>>ARRAY['session_message:'||(m->>'parentId'),'source','held'] IS DISTINCT FROM 'false' THEN RETURN NULL;END IF;
  ELSIF n#>>'{node,kind}'='workspace_file' THEN
   -- v2 uses the already evaluated current department envelope. Legacy files
   -- additionally enforce their original direct membership/project predicates.
   IF v2 IS NOT TRUE AND (member_operation_scope_allows(w,source->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(source->'compartments')),false) IS NOT TRUE
    OR agent_read_scope_allows(source->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(source->'compartments')),ARRAY(SELECT jsonb_array_elements_text(source->'projectIds')::uuid)) IS NOT TRUE
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(source->'projectIds') p WHERE NOT EXISTS(SELECT 1 FROM workspace_projects pr
      WHERE pr.workspace_id=w AND pr.id=p::uuid AND pr.status='active' AND(member_role IN('owner','admin')
       OR EXISTS(SELECT 1 FROM workspace_project_members pm WHERE pm.project_id=p::uuid AND pm.user_id=actor))))) THEN RETURN NULL;END IF;
  ELSE RETURN NULL;END IF;
  currents:=currents||jsonb_build_object((n#>>'{node,kind}')||':'||(n#>>'{node,id}'),jsonb_build_object('source',source));
 END LOOP;
 RETURN jsonb_build_object('workspaceId',w,'closed',true,'currents',currents,'context',jsonb_build_object('parents',parents));
END $$;

-- Locks preserve the old source/parent mutation protocol. Metadata discovery is
-- not admission; the following statement recomputes the complete current graph.
CREATE FUNCTION native_turn_lock_requirements(w uuid,meta jsonb) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 acting uuid:=nullif(current_setting('app.v2_assistant_id',true),'')::uuid;node record;
BEGIN
 IF meta->>'eligibleMetadata' IS DISTINCT FROM 'true' OR meta#>>'{witness,context,workspaceId}' IS DISTINCT FROM w::text THEN RETURN false;END IF;
 PERFORM id FROM workspaces WHERE id=w FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;
 PERFORM user_id FROM workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;
 IF acting IS NOT NULL THEN PERFORM id FROM assistants WHERE workspace_id=w AND id=acting FOR SHARE;IF NOT FOUND THEN RETURN false;END IF;END IF;
 PERFORM id FROM workspace_groups WHERE workspace_id=w AND kind='team' ORDER BY id FOR SHARE;
 PERFORM id FROM department_edges WHERE workspace_id=w AND(user_id=actor OR assistant_id=acting) ORDER BY id FOR SHARE;
 PERFORM id FROM sessions WHERE workspace_id=w AND id IN(SELECT (value->>'id')::uuid FROM jsonb_array_elements(meta#>'{witness,sessionParents}')) ORDER BY id FOR SHARE;
 FOR node IN SELECT DISTINCT value#>>'{node,kind}' kind,(value#>>'{node,id}')::uuid id FROM jsonb_array_elements(meta#>'{witness,nativeMetadata}') ORDER BY kind,id LOOP
  IF node.kind='session_message' THEN PERFORM id FROM session_messages WHERE workspace_id=w AND id=node.id FOR SHARE;
  ELSIF node.kind='session_context_revision' THEN PERFORM id FROM session_context_scope_revisions WHERE workspace_id=w AND id=node.id FOR SHARE;
  ELSIF node.kind='workspace_file' THEN PERFORM id FROM workspace_files WHERE workspace_id=w AND id=node.id FOR SHARE;
  ELSE RETURN false;END IF;
  IF NOT FOUND THEN RETURN false;END IF;
 END LOOP;
 PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;IF NOT FOUND THEN RETURN false;END IF;
 PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;IF NOT FOUND THEN RETURN false;END IF;
 PERFORM id FROM workspace_projects WHERE workspace_id=w AND id IN(
  SELECT pid.value::uuid FROM jsonb_array_elements(meta#>'{witness,nativeMetadata}') n CROSS JOIN LATERAL jsonb_array_elements_text(n#>'{metadata,projectIds}') pid(value)
  UNION SELECT (p->>'contextProjectId')::uuid FROM jsonb_array_elements(meta#>'{witness,sessionParents}') p WHERE p->>'contextProjectId' IS NOT NULL
 ) ORDER BY id FOR SHARE;
 RETURN true;
EXCEPTION WHEN lock_not_available THEN RETURN false;
END $$;

CREATE FUNCTION native_turn_capture_requirements(w uuid,roots jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE meta jsonb;frame jsonb;source_nodes jsonb;point_values jsonb:='[]';immutable jsonb:='[]';currents jsonb:='[]';
 nodes_by_key jsonb;original_keys jsonb;root_kinds text[];root_ids uuid[];root_versions text[];node jsonb;result jsonb;source jsonb;key text;dependency jsonb;derivation jsonb;
 memo jsonb:='{"nativeWorklist":true}';observed_at timestamptz:=clock_timestamp();deadline timestamptz;
 memory_context jsonb;observation application_field_observations;
BEGIN
 IF nullif(current_setting('app.current_user_id',true),'') IS NULL OR EXISTS(
  SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='session_messages'::regclass WHERE r.rolname=session_user
  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE'))) THEN
  RAISE EXCEPTION 'native_turn_principal_required' USING ERRCODE='42501';END IF;
 IF native_turn_helpers_current() IS NOT TRUE THEN RETURN jsonb_build_object('available',false,'reason','reader_contract_changed');END IF;
 meta:=native_turn_metadata_acquire(w,roots);
 IF meta->>'eligibleMetadata' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('available',false,'reason','unsupported_requirements');END IF;
 SELECT coalesce(min(t),'infinity'::timestamptz) INTO deadline FROM(
 SELECT expires_at t FROM department_edges WHERE expires_at>transaction_timestamp()
 UNION ALL SELECT starts_at FROM workspace_access_grants WHERE starts_at>transaction_timestamp()
 UNION ALL SELECT expires_at FROM workspace_access_grants WHERE expires_at>transaction_timestamp()
 UNION ALL SELECT expires_at FROM project_shared_members WHERE expires_at>transaction_timestamp()
 UNION ALL SELECT starts_at FROM application_native_role_assignments WHERE starts_at>transaction_timestamp()
 UNION ALL SELECT expires_at FROM application_native_role_assignments WHERE expires_at>transaction_timestamp()
 UNION ALL SELECT expires_at FROM office_artifacts WHERE expires_at>transaction_timestamp()) transitions;
 SELECT jsonb_object_agg(native_turn_key(n),n),jsonb_agg(n-'tag' ORDER BY n->>'kind',n->>'id',n->>'version') FILTER(WHERE n->>'tag'='source')
 INTO nodes_by_key,source_nodes FROM jsonb_array_elements(meta#>'{witness,nodes}') n;
 frame:=native_turn_capture_sources(w,meta);
 IF frame IS NULL OR frame->>'closed' IS DISTINCT FROM 'true' OR EXISTS(
 SELECT 1 FROM jsonb_each(frame->'currents') e WHERE e.value#>>'{source,held}' IS DISTINCT FROM 'false'
  OR e.value#>>'{source,validTo}' IS NOT NULL OR e.value#>>'{source,retractedAt}' IS NOT NULL)
 THEN RETURN jsonb_build_object('available',false,'reason','source_admission');END IF;
 WITH RECURSIVE physical(parent,child) AS MATERIALIZED(
  SELECT value->'parent',value->'child' FROM jsonb_array_elements(meta#>'{witness,edges}')
  WHERE value->>'edge_kind' IN('derivation','observation','observation_child','predecessor')
 ), original(n) AS(
  SELECT value||'{"tag":"source"}'::jsonb FROM jsonb_array_elements(roots)
  UNION SELECT p.child FROM original o JOIN physical p ON p.parent=o.n
 ) SELECT jsonb_object_agg((n->>'kind')||':'||(n->>'id')||':'||(n->>'version'),true) INTO original_keys FROM original;
 frame:=frame||jsonb_build_object('edges',(SELECT jsonb_object_agg((n->>'kind')||':'||(n->>'id')||':'||(n->>'version'),'[]'::jsonb) FROM jsonb_array_elements(source_nodes) n));
 IF original_keys IS NULL THEN RETURN jsonb_build_object('available',false,'reason','original_cohort');END IF;
 -- The complete all-version recording graph was checked before any payload.
 frame:=frame||jsonb_build_object('validUntil',deadline,'points','{}'::jsonb,'fields','{}'::jsonb,'scopes','{}'::jsonb,
  'sourceKeys',(SELECT jsonb_object_agg((n->>'kind')||':'||(n->>'id')||':'||(n->>'version'),true) FROM jsonb_array_elements(source_nodes) n),
  'privacyCovered',(SELECT jsonb_object_agg((n->>'kind')||':'||(n->>'id'),true) FROM jsonb_array_elements(meta#>'{witness,privacyNodes}') n));
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(meta#>'{witness,fieldMetadata}') f WHERE f#>>'{resource,type_key}'='memory') THEN
  memory_context:=native_turn_empty_memory_context(w);
  IF memory_context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' OR EXISTS(SELECT 1 FROM memories WHERE workspace_id=w)
   OR EXISTS(SELECT 1 FROM application_native_resource_owners WHERE workspace_id=w AND origin='{"kind":"native","moduleKey":"native"}' AND resource_type='memory')
   THEN RETURN jsonb_build_object('available',false,'reason','memory_requirements');END IF;
  memo:=memo||jsonb_build_object('memoryStatement',jsonb_build_object('workspaceId',w,'context',memory_context,'rows','{}'::jsonb,'cohort','[]'::jsonb));
 END IF;
 BEGIN
 FOR derivation IN SELECT value FROM jsonb_array_elements(meta#>'{witness,derivations}') LOOP
  IF workflow_evidence_envelope_visible(w,jsonb_build_object('workspaceId',w,'userId',derivation->'user_id',
   'assistantId',derivation->'assistant_id','sensitivity',derivation->'sensitivity','compartments',derivation->'compartments','projectIds',derivation->'project_ids')) IS NOT TRUE
  THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 END LOOP;
 FOR key IN SELECT jsonb_array_elements_text(meta->'evaluationOrder') LOOP
  node:=nodes_by_key->key;
  IF node->>'tag'='point' THEN
   result:=native_turn_read_point(w,node->>'kind',(node->>'id')::uuid,ARRAY(SELECT jsonb_array_elements_text(node->'fields')),memo,frame);
   frame:=jsonb_set(frame,'{points}',(frame->'points')||jsonb_build_object(jsonb_build_array(node->>'kind',(node->>'id')::uuid,node->'fields')::text,coalesce(result->'value','null'::jsonb)));
   point_values:=point_values||jsonb_build_array(jsonb_build_object('node',node,'state',result->'value'));
  ELSIF node->>'kind'='application_field' THEN
   result:=native_turn_reduce_field(w,(node->>'id')::uuid,node->>'version',memo,frame);source:=result->'value';
   IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   frame:=jsonb_set(frame,'{fields}',(frame->'fields')||jsonb_build_object((node->>'id')||':'||(node->>'version'),source));
   SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(node->>'id')::uuid AND version=node->>'version';
   IF original_keys ? ((node->>'kind')||':'||(node->>'id')||':'||(node->>'version')) THEN
   immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object('resourceKind','application_field','resourceId',observation.resource_id,'version',observation.version));
   currents:=currents||jsonb_build_array(source-ARRAY['held','validTo','retractedAt']);END IF;
  ELSIF node->>'kind' IN('session_message','session_context_revision','workspace_file') THEN
   -- This complete acyclic schedule has already evaluated every dependency.
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(meta#>'{witness,edges}') edge
    WHERE edge->'parent'=node AND edge#>>'{child,kind}'='application_field'
     AND frame#>>ARRAY['fields',(edge#>>'{child,id}')||':'||(edge#>>'{child,version}'),'held'] IS DISTINCT FROM 'false')
   THEN RAISE EXCEPTION 'native_turn_requirement_unresolved' USING ERRCODE='PNT01';END IF;
   source:=frame#>ARRAY['currents',(node->>'kind')||':'||(node->>'id'),'source'];
   IF source IS NULL OR source->>'held' IS DISTINCT FROM 'false' OR workflow_evidence_envelope_visible(w,source) IS NOT TRUE THEN
    RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   frame:=jsonb_set(frame,'{scopes}',(frame->'scopes')||jsonb_build_object((node->>'kind')||':'||(node->>'id')||':'||(node->>'version'),true));
   source:=jsonb_build_object('workspaceId',w,'userId',source->'userId','assistantId',source->'assistantId','sensitivity',source->'sensitivity',
    'compartments',source->'compartments','projectIds',source->'projectIds','resourceKind',node->'kind','resourceId',node->'id','version',source->'version');
   IF original_keys ? ((node->>'kind')||':'||(node->>'id')||':'||(node->>'version')) THEN
   currents:=currents||jsonb_build_array(source);
   IF node->>'kind'='session_context_revision' THEN
    IF source->>'version' IS DISTINCT FROM node->>'version' THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
    immutable:=immutable||jsonb_build_array(source);
   END IF;END IF;
  END IF;
 END LOOP;
 EXCEPTION WHEN insufficient_privilege OR SQLSTATE 'PNT01' THEN
  RETURN jsonb_build_object('available',false,'reason','requirements_unavailable');
 END;
 IF native_turn_helpers_current() IS NOT TRUE THEN RETURN jsonb_build_object('available',false,'reason','reader_contract_changed');END IF;
 IF clock_timestamp()>=deadline THEN RAISE EXCEPTION 'native_turn_policy_expired' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('available',true,'admitted',true,'validUntil',deadline,'counts',meta->'counts',
  'immutable',(SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]') FROM jsonb_array_elements(immutable) v),
  'current',(SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]') FROM jsonb_array_elements(currents) v),
  'points',point_values,'requirements',meta->'witness');
END $$;

CREATE FUNCTION read_native_turn_requirements(w uuid,roots jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result jsonb;context jsonb;discovered jsonb;
BEGIN
 context:=native_turn_context();
 IF native_turn_helpers_current() IS NOT TRUE THEN RETURN jsonb_build_object('available',false,'reason','reader_contract_changed');END IF;
 discovered:=native_turn_metadata_acquire(w,roots);
 IF discovered->>'eligibleMetadata' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('available',false,'reason','unsupported_requirements');END IF;
 IF native_turn_lock_requirements(w,discovered) IS NOT TRUE THEN RETURN jsonb_build_object('available',false,'reason','lock_coverage');END IF;
 SELECT native_turn_capture_requirements(w,roots) INTO result;
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_context() IS DISTINCT FROM context THEN RETURN jsonb_build_object('available',false,'reason','reader_contract_changed');END IF;
 IF result->>'available'='true' AND (
  result#>'{requirements,nativeMetadata}' IS DISTINCT FROM discovered#>'{witness,nativeMetadata}'
  OR result#>'{requirements,sessionParents}' IS DISTINCT FROM discovered#>'{witness,sessionParents}')
 THEN RETURN jsonb_build_object('available',false,'reason','lock_coverage');END IF;
 IF result->>'available'='true' AND clock_timestamp()>=(result->>'validUntil')::timestamptz THEN
  RAISE EXCEPTION 'native_turn_policy_expired' USING ERRCODE='42501';END IF;
 RETURN result;
END $$;
CREATE FUNCTION read_native_turn_scope_evidence(w uuid,roots jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result jsonb;
BEGIN
 result:=read_native_turn_requirements(w,roots);
 IF result->>'available' IS DISTINCT FROM 'true' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('admitted',true,'immutable',result->'immutable','current',result->'current');
END $$;
REVOKE ALL ON FUNCTION read_native_turn_scope_evidence(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION read_native_turn_scope_evidence(uuid,jsonb) TO app_user;
DO $$ DECLARE f regprocedure; BEGIN FOR f IN SELECT oid::regprocedure FROM pg_proc
 WHERE pronamespace='public'::regnamespace AND(proname LIKE 'native_turn_%' OR proname='read_native_turn_requirements')
 LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,app_user',f);
 IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=f AND(p.proowner<>(SELECT relowner FROM pg_class WHERE oid='memories'::regclass)
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
   WHERE a.grantee<>p.proowner OR a.grantor<>p.proowner OR a.is_grantable OR a.privilege_type<>'EXECUTE')))
 THEN RAISE EXCEPTION 'native_turn_private_acl: %',f;END IF;
 END LOOP;END $$;
