 SELECT p.oid::regprocedure::text,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p
 WHERE p.pronamespace='public'::regnamespace AND(p.proname LIKE 'native_worklist_source_%'
  OR p.proname IN('native_worklist_current_application_sources','read_scope_source','read_scope_source_before_knowledge_binding',
   'scope_source_table','scope_source_table_before_knowledge_versions','session_context_revision_native','session_context_revision_snapshot'))
 ON CONFLICT DO NOTHING;
-- The roster is immutable executable metadata, not a permission-result cache.
DO $seal$
DECLARE roster text;body text;
BEGIN
 SELECT string_agg(quote_literal(signature),',' ORDER BY signature) INTO roster FROM native_turn_contract_helpers;
 SELECT prosrc INTO body FROM pg_proc WHERE oid='native_turn_helpers_current()'::regprocedure;
 body:=replace(body,'count(*)>0','array_agg(h.signature ORDER BY h.signature)=ARRAY['||roster||']::text[]');
 EXECUTE 'CREATE OR REPLACE FUNCTION native_turn_helpers_current() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS '||quote_literal(body);
 UPDATE native_turn_contract_helpers h SET fingerprint=encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')
 FROM pg_proc p WHERE p.oid='native_turn_helpers_current()'::regprocedure AND h.signature=p.oid::regprocedure::text;
END $seal$;

COMMIT;